_trading_sim_schema_done = False

def _trading_sim_service():
    from src.trading.simulation import TradingSimulationService
    return TradingSimulationService()


def _ensure_trading_sim_schema_once():
    global _trading_sim_schema_done
    if _trading_sim_schema_done:
        return
    try:
        with _trading_sim_conn(timeout=10) as conn:
            _ensure_trading_sim_schema_once()
        _trading_sim_schema_done = True
    except Exception:
        pass


def _trading_sim_conn(timeout: int = 15):
    conn = db_connect(DB_PATH, timeout=timeout)
    conn.row_factory = sqlite3.Row
    return conn


def _trading_sim_filters_from_request():
    now = int(time.time())
    risk_level = (request.args.get('risk_level') or '').strip().upper() or None
    if risk_level not in {None, 'CRITICAL', 'HIGH', 'MEDIUM', 'WATCH', 'LOW', 'UNKNOWN', 'LIQ', 'WATCH-T'}:
        risk_level = None
    strategy = (request.args.get('strategy') or 'current').strip().lower()
    if strategy not in {
        'current', 'peak', 'cascade',
        'target_1_5', 'target_2_5', 'target_3', 'target_3_5',
        'target_5', 'target_7', 'target_10', 'watch_trailing',
    }:
        strategy = 'current'

    opened_since = None
    opened_before = None
    time_window = (request.args.get('time_window') or '').strip()
    if time_window == '24+':
        opened_before = now - 86400
    elif time_window:
        try:
            hours = float(time_window)
            if hours > 0:
                opened_since = now - int(hours * 3600)
        except ValueError:
            pass
    return {
        "risk_level": risk_level,
        "opened_since": opened_since,
        "opened_before": opened_before,
        "strategy": strategy,
    }


