# ── Phase 2 Lite: second-hop funder RPC expansion ─────────────────────────────

@app.route('/api/second-hop-lite/status')
def api_second_hop_lite_status():
    """
    Return Phase 2 Lite tracking status.
    Gracefully returns empty data if tables are not yet created.
    """
    import datetime as _dt
    _log = logging.getLogger(__name__)
    try:
        conn = db_connect(DB_PATH, timeout=10)
        conn.row_factory = sqlite3.Row

        def _table_exists(name: str) -> bool:
            return conn.execute(
                "SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name=?",
                (name,)
            ).fetchone()[0] == 1

        queue_ok  = _table_exists("second_hop_lite_queue")
        cache_ok  = _table_exists("funder_rpc_scan_cache")
        log_ok    = _table_exists("second_hop_lite_rpc_log")

        # ── Enabled flag — DB setting takes priority over env var ────────────
        import os as _os
        enabled = _os.getenv("SECOND_HOP_RPC_LITE_ENABLED", "false").lower() == "true"
        try:
            row = conn.execute(
                "SELECT setting_value FROM listener_settings WHERE setting_key='second_hop_lite_enabled'"
            ).fetchone()
            if row is not None:
                enabled = row['setting_value'] == 'true'
        except Exception:
            pass

        # ── Priority funders (same logic as queue builder) ────────────────────
        priority_funders = 0
        try:
            priority_funders = conn.execute("""
                SELECT COUNT(DISTINCT funder_address)
                FROM creator_funders
                WHERE is_cex = 0
                  AND funder_address IN (
                      SELECT funder_address FROM creator_funders
                      WHERE is_cex = 0
                      GROUP BY funder_address
                      HAVING COUNT(DISTINCT creator_address) >= 2
                  )
            """).fetchone()[0] or 0
        except Exception:
            pass

        # ── Tracked funders ───────────────────────────────────────────────────
        tracked_funders = 0
        try:
            cache_set = set()
            link_set  = set()
            if cache_ok:
                cache_set = {
                    r[0] for r in conn.execute(
                        "SELECT DISTINCT funder_address FROM funder_rpc_scan_cache"
                    ).fetchall()
                }
            link_set = {
                r[0] for r in conn.execute(
                    "SELECT DISTINCT funder_address FROM funder_upstream_links"
                ).fetchall()
            }
            # Intersect with the priority set
            priority_set_rows = conn.execute("""
                SELECT funder_address FROM creator_funders
                WHERE is_cex = 0
                GROUP BY funder_address
                HAVING COUNT(DISTINCT creator_address) >= 2
            """).fetchall()
            priority_set = {r[0] for r in priority_set_rows}
            tracked_funders = len(priority_set & (cache_set | link_set))
        except Exception:
            pass

        # ── Queue stats ───────────────────────────────────────────────────────
        queue_stats = {"pending": 0, "done": 0, "failed": 0, "scanning": 0, "skipped": 0}
        if queue_ok:
            try:
                rows = conn.execute("""
                    SELECT status, COUNT(*) AS cnt
                    FROM second_hop_lite_queue
                    GROUP BY status
                """).fetchall()
                for r in rows:
                    queue_stats[r["status"]] = r["cnt"]
            except Exception:
                pass

        # ── Top untracked funders (pending in queue) ──────────────────────────
        top_untracked = []
        if queue_ok:
            try:
                rows = conn.execute("""
                    SELECT q.funder_address, q.priority, q.reason_codes,
                           COALESCE(fc.creator_count, 0) AS creator_count,
                           CASE
                               WHEN EXISTS (SELECT 1 FROM infra_funders_observed WHERE funder_address=q.funder_address) THEN 'INFRA'
                               WHEN MAX(cf2.is_cex) = 1 THEN 'CEX'
                               ELSE NULL
                           END AS cex_infra_label
                    FROM second_hop_lite_queue q
                    LEFT JOIN (
                        SELECT funder_address, COUNT(DISTINCT creator_address) AS creator_count
                        FROM creator_funders WHERE is_cex=0
                        GROUP BY funder_address
                    ) fc ON fc.funder_address = q.funder_address
                    LEFT JOIN creator_funders cf2 ON cf2.funder_address = q.funder_address
                    WHERE q.status = 'pending'
                    GROUP BY q.funder_address
                    ORDER BY q.priority DESC
                    LIMIT 10
                """).fetchall()
                import json as _json
                for r in rows:
                    d = dict(r)
                    try:
                        d["reason_codes"] = _json.loads(d["reason_codes"] or "[]")
                    except Exception:
                        d["reason_codes"] = []
                    top_untracked.append(d)
            except Exception:
                pass

        # ── Recent scans ──────────────────────────────────────────────────────
        recent_scans = []
        if cache_ok:
            try:
                rows = conn.execute("""
                    SELECT q.funder_address,
                           COALESCE(src.inbound_upstream_count, 0) AS inbound_upstream_count,
                           COALESCE(src.rpc_calls_used, 0) AS rpc_calls_used,
                           q.scanned_at,
                           COALESCE(src.status, 'cache_hit') AS status
                    FROM second_hop_lite_queue q
                    LEFT JOIN funder_rpc_scan_cache src ON src.funder_address = q.funder_address
                    WHERE q.status = 'done' AND q.scanned_at IS NOT NULL
                    ORDER BY q.scanned_at DESC
                    LIMIT 20
                """).fetchall()
                scans = [dict(r) for r in rows]

                # Enrich with networks, upstream links, and 2H creator connections
                for s in scans:
                    addr = s["funder_address"]
                    try:
                        nets = conn.execute(
                            "SELECT network_name FROM funder_network_map WHERE funder_address=?", (addr,)
                        ).fetchall()
                        s["networks"] = [r[0] for r in nets]
                    except Exception:
                        s["networks"] = []
                    try:
                        ul = conn.execute(
                            "SELECT COUNT(*) FROM funder_upstream_links WHERE funder_address=?", (addr,)
                        ).fetchone()
                        s["upstream_links"] = ul[0] if ul else 0
                    except Exception:
                        s["upstream_links"] = 0
                    try:
                        sh = conn.execute(
                            "SELECT COUNT(*) FROM creator_second_hop WHERE via_funder=?", (addr,)
                        ).fetchone()
                        s["second_hop_creators"] = sh[0] if sh else 0
                    except Exception:
                        s["second_hop_creators"] = 0
                    try:
                        is_infra = conn.execute(
                            "SELECT 1 FROM infra_funders_observed WHERE funder_address=?", (addr,)
                        ).fetchone()
                        is_cex = conn.execute(
                            "SELECT MAX(is_cex) FROM creator_funders WHERE funder_address=?", (addr,)
                        ).fetchone()
                        if is_infra:
                            s["cex_infra_label"] = "INFRA"
                        elif is_cex and is_cex[0]:
                            s["cex_infra_label"] = "CEX"
                        else:
                            s["cex_infra_label"] = None
                    except Exception:
                        s["cex_infra_label"] = None

                recent_scans = scans
            except Exception:
                pass

        # ── RPC calls today ───────────────────────────────────────────────────
        rpc_calls_today = 0
        if log_ok:
            try:
                today_midnight = int(
                    _dt.datetime.now(_dt.timezone.utc)
                    .replace(hour=0, minute=0, second=0, microsecond=0)
                    .timestamp()
                )
                rpc_calls_today = conn.execute("""
                    SELECT COUNT(*) FROM second_hop_lite_rpc_log
                    WHERE called_at >= ? AND cache_hit = 0
                """, (today_midnight,)).fetchone()[0] or 0
            except Exception:
                pass

        # ── Cache hit rate (last 7 days) ──────────────────────────────────────
        cache_hit_rate = None
        if log_ok:
            try:
                week_ago = int(time.time()) - 7 * 86400
                total_calls, cache_hits = conn.execute("""
                    SELECT COUNT(*), SUM(cache_hit)
                    FROM second_hop_lite_rpc_log
                    WHERE called_at >= ?
                """, (week_ago,)).fetchone()
                if total_calls:
                    cache_hit_rate = round((cache_hits or 0) / total_calls * 100, 1)
            except Exception:
                pass

        conn.close()

        # True only while the background thread holds the lock (started after end)
        run_in_progress = _shl_last_run_start > 0 and _shl_last_run_start > _shl_last_run_end

        # ── Upstream hub stats ────────────────────────────────────────────────
        upstream_hubs = 0
        hub_expansions_24h = 0
        try:
            upstream_hubs = conn.execute(
                "SELECT COUNT(*) FROM monitored_upstream_hubs WHERE status='active'"
            ).fetchone()[0] or 0
            today_cutoff = int(time.time()) - 86400
            hub_expansions_24h = conn.execute(
                "SELECT COUNT(*) FROM monitored_upstream_hubs WHERE last_expanded_at >= ?",
                (today_cutoff,)
            ).fetchone()[0] or 0
        except Exception:
            pass

        return jsonify({
            "enabled": enabled,
            "tables_ready": queue_ok and cache_ok and log_ok,
            "priority_funders": priority_funders,
            "tracked_funders": tracked_funders,
            "queue": queue_stats,
            "rpc_calls_today": rpc_calls_today,
            "cache_hit_rate": cache_hit_rate,
            "top_untracked_funders": top_untracked,
            "recent_scans": recent_scans,
            "run_in_progress": run_in_progress,
            "upstream_hubs": upstream_hubs,
            "hub_expansions_24h": hub_expansions_24h,
        })

    except Exception as exc:
        _log.exception("[second-hop-lite/status] failed")
        return jsonify({"error": str(exc)}), 500


@app.route('/api/second-hop-lite/enqueue/<funder_address>', methods=['POST'])
def api_second_hop_lite_enqueue(funder_address):
    """
    Manually enqueue a funder address for RPC scanning.
    Does not trigger a scan — just inserts into the queue at medium priority (50).
    """
    _log = logging.getLogger(__name__)
    try:
        conn = db_connect(DB_PATH, timeout=10)
        conn.row_factory = sqlite3.Row

        # Validate: funder must exist in creator_funders
        exists = conn.execute(
            "SELECT 1 FROM creator_funders WHERE funder_address=? AND is_cex=0 LIMIT 1",
            (funder_address,)
        ).fetchone()
        if not exists:
            conn.close()
            return jsonify({"error": "funder not found or is CEX"}), 404

        import json as _json
        now = int(time.time())
        conn.execute("""
            INSERT OR IGNORE INTO second_hop_lite_queue (
                funder_address, priority, reason_codes,
                status, attempts, rpc_calls_used,
                created_at, next_attempt_at
            ) VALUES (?, 50, ?, 'pending', 0, 0, ?, ?)
        """, (funder_address, _json.dumps(["manual_enqueue"]), now, now))
        conn.commit()
        conn.close()
        return jsonify({"status": "enqueued", "funder_address": funder_address})

    except Exception as exc:
        _log.exception("[second-hop-lite/enqueue] failed")
        return jsonify({"error": str(exc)}), 500


@app.route('/api/second-hop-lite/rescan/<funder_address>', methods=['POST'])
def api_second_hop_lite_rescan(funder_address):
    """
    Force-rescan a funder: resets its queue entry to pending and clears the
    RPC scan cache so the worker will re-fetch from Helius.
    """
    _log = logging.getLogger(__name__)
    try:
        conn = db_connect(DB_PATH, timeout=10)
        conn.row_factory = sqlite3.Row

        now = int(time.time())

        # Clear cache entry so the worker won't use stale data
        try:
            conn.execute(
                "DELETE FROM funder_rpc_scan_cache WHERE funder_address=?",
                (funder_address,)
            )
        except sqlite3.OperationalError:
            pass

        # Reset or insert queue entry
        try:
            updated = conn.execute("""
                UPDATE second_hop_lite_queue
                SET status='pending', next_attempt_at=?, last_error=NULL
                WHERE funder_address=?
            """, (now, funder_address)).rowcount
            if not updated:
                import json as _json
                conn.execute("""
                    INSERT OR IGNORE INTO second_hop_lite_queue (
                        funder_address, priority, reason_codes,
                        status, attempts, rpc_calls_used,
                        created_at, next_attempt_at
                    ) VALUES (?, 60, ?, 'pending', 0, 0, ?, ?)
                """, (funder_address, _json.dumps(["manual_rescan"]), now, now))
        except sqlite3.OperationalError as exc:
            conn.close()
            return jsonify({"error": f"Queue table not ready: {exc}"}), 503

        conn.commit()
        conn.close()
        return jsonify({"status": "reset_to_pending", "funder_address": funder_address})

    except Exception as exc:
        _log.exception("[second-hop-lite/rescan] failed")
        return jsonify({"error": str(exc)}), 500


@app.route('/api/second-hop-lite/toggle', methods=['POST'])
def api_second_hop_lite_toggle():
    """Enable or disable Phase 2 Lite RPC scanning. Persisted in listener_settings."""
    _log = logging.getLogger(__name__)
    try:
        data = request.get_json(silent=True) or {}
        new_enabled = bool(data.get('enabled', False))
        val = 'true' if new_enabled else 'false'
        from datetime import datetime as _datetime
        now_str = _datetime.utcnow().strftime('%Y-%m-%d %H:%M:%S')

        conn = db_connect(DB_PATH, timeout=10)
        conn.execute("""
            INSERT INTO listener_settings (setting_key, setting_value, description, last_updated)
            VALUES ('second_hop_lite_enabled', ?, 'Phase 2 Lite RPC scanning on/off', ?)
            ON CONFLICT(setting_key) DO UPDATE SET setting_value=excluded.setting_value, last_updated=excluded.last_updated
        """, (val, now_str))
        conn.commit()
        conn.close()

        status = 'ON' if new_enabled else 'OFF'
        _log.info(f"[second-hop-lite] RPC scanning toggled {status}")
        return jsonify({"enabled": new_enabled, "status": status})

    except Exception as exc:
        _log.exception("[second-hop-lite/toggle] failed")
        return jsonify({"error": str(exc)}), 500


# Prevents concurrent Run Now executions
import threading as _threading
_shl_lock = _threading.Lock()
_shl_last_run_start: float = 0.0
_shl_last_run_end: float = 0.0

@app.route('/api/second-hop-lite/run-now', methods=['POST'])
def api_second_hop_lite_run_now():
    """
    Trigger a Phase 2 Lite worker run in a background thread.
    Also runs SecondHopExpansionBuilder and NetworksReleaseBuilder afterward
    so the bridge tables and UI update immediately.
    Returns immediately — poll /api/second-hop-lite/status to see results.
    """
    global _shl_last_run_start, _shl_last_run_end
    _log = logging.getLogger(__name__)
    import time as _time

    if not _shl_lock.acquire(blocking=False):
        return jsonify({"status": "already_running", "message": "Worker is already running"}), 409

    _shl_last_run_start = _time.time()

    def _run():
        import traceback
        _dbg = open("/Users/kevinkeaveney/Dev/claude/flex/logs/run_now_debug.log", "a")
        def _w(msg):
            import time as _t
            _dbg.write(f"{_t.strftime('%H:%M:%S')} {msg}\n")
            _dbg.flush()
        try:
            import os as _os
            _os.environ['SECOND_HOP_RPC_LITE_ENABLED'] = 'true'
            _os.environ['SECOND_HOP_SQL_ENABLED'] = 'true'

            from src.core.second_hop_lite_worker import SecondHopLiteWorker
            from src.core.second_hop_builder import SecondHopExpansionBuilder
            from src.utils.build_networks_release import build_networks_release

            _w("Starting RPC worker")
            import time as _wt
            _worker_started_at = int(_wt.time())
            try:
                worker_result = SecondHopLiteWorker(DB_PATH).run(force=True)
                _w(f"RPC worker done: {worker_result}")
            except Exception as _e:
                _w(f"RPC worker EXCEPTION: {traceback.format_exc()}")
                raise

            _w("Rebuilding bridges")
            bridge_result = SecondHopExpansionBuilder(DB_PATH).build()
            _w(f"Bridges done: {bridge_result}")

            _w("Rebuilding networks release")
            build_networks_release(DB_PATH)

            _w("Running RiskScoringBuilder (incremental)")
            try:
                from src.core.risk_scoring_builder import RiskScoringBuilder
                import sqlite3 as _rs_sqlite
                # Find creators affected by the funders just scanned in this batch
                _rs_conn = _rs_sqlite.connect(DB_PATH, timeout=10)
                _rs_conn.execute("PRAGMA journal_mode=WAL")
                _scanned_funders = [
                    r[0] for r in _rs_conn.execute(
                        "SELECT funder_address FROM second_hop_lite_queue WHERE status='done' AND scanned_at >= ?",
                        (_worker_started_at,)
                    ).fetchall()
                ]
                _affected_creators = [
                    r[0] for r in _rs_conn.execute(
                        f"SELECT DISTINCT creator_address FROM creator_funders WHERE funder_address IN ({','.join('?'*len(_scanned_funders))})",
                        _scanned_funders
                    ).fetchall()
                ] if _scanned_funders else []
                _rs_conn.close()
                _w(f"Incremental rescore: {len(_scanned_funders)} funders → {len(_affected_creators)} creators")
                if _affected_creators:
                    _risk_result = RiskScoringBuilder(DB_PATH).run_incremental(_affected_creators)
                    _w(f"Risk scoring done: {_risk_result}")
                else:
                    _w("No affected creators — skipping risk rescore")
            except Exception as _risk_e:
                _w(f"Risk scoring failed: {_risk_e}")

            _w("Running IntelligenceRefreshCandidateBuilder")
            import time as _irc_time
            _irc_t0 = _irc_time.time()
            _irc_status = "failed"
            try:
                from src.core.intelligence_refresh import (
                    IntelligenceRefreshCandidateBuilder, apply_migration as _irc_migrate
                )
                _irc_migrate(DB_PATH)
                _irc_result = IntelligenceRefreshCandidateBuilder(DB_PATH).run()
                _irc_status = _irc_result.get("status", "success")
            except Exception as _irc_e:
                _w(f"IRC failed: {_irc_e}")
            finally:
                import sqlite3 as _irc_sqlite
                try:
                    _ic = _irc_sqlite.connect(DB_PATH, timeout=10)
                    _ic.execute("PRAGMA journal_mode=WAL")
                    _ic.execute("""
                        INSERT INTO analyzer_runs
                            (analyzer_name, started_at, finished_at, duration_seconds, status, rows_written, created_at)
                        VALUES ('IntelligenceRefreshCandidateBuilder',?,?,?,?,0,?)
                    """, (_irc_t0, _irc_time.time(), round(_irc_time.time()-_irc_t0,2), _irc_status, _irc_time.time()))
                    _ic.commit()
                    _ic.close()
                except Exception:
                    pass
            _w("Pipeline complete")

        except Exception as exc:
            _w(f"FAILED: {traceback.format_exc()}")
        finally:
            _shl_last_run_end = _time.time()
            _dbg.close()
            _shl_lock.release()

    import threading
    t = threading.Thread(target=_run, daemon=True)
    t.start()
    return jsonify({"status": "started", "message": "Worker running in background — refresh status in a few seconds"})


@app.route('/networks')
def networks_dashboard():
    """Serve a full webview for atomic funder networks"""

    def new_path():
        """NEW PATH: Use precomputed networks_release"""
        all_networks = get_networks_release_list(include_evidence=False)

        # Batch fetch all network scores (using JOIN for better scalability than IN clause)
        scores_map = {}
        try:
            conn, cursor = get_db_conn()
            # Build a temporary table from network_names for efficient JOIN
            # (Avoids long IN clause with hundreds/thousands of names)
            cursor.execute('DROP TABLE IF EXISTS temp_networks')
            cursor.execute('CREATE TEMP TABLE temp_networks (network_name TEXT PRIMARY KEY)')

            # Insert all network names
            for network in all_networks:
                cursor.execute('INSERT INTO temp_networks (network_name) VALUES (?)',
                             (network['network_name'],))

            # Join with network_scores to fetch scores efficiently
            cursor.execute('''
                SELECT tn.network_name, ns.score
                FROM temp_networks tn
                LEFT JOIN network_scores ns USING (network_name)
            ''')

            for row in cursor.fetchall():
                if row['score'] is not None:  # Only add if score exists
                    scores_map[row['network_name']] = {
                        'score': row['score'],
                        'components': {}
                    }

            cursor.execute('DROP TABLE IF EXISTS temp_networks')
            conn.close()
        except Exception as e:
            print(f"[DEBUG] Error fetching network scores: {e}")

        networks = []
        total_tokens = 0
        total_creators_funded = 0
        total_sol = 0.0

        # Bulk fetch creators-per-network and token counts in 2 queries instead of 108×2
        creators_by_network = {}  # network_name -> [creator_address]
        token_count_by_network = {}  # network_name -> int
        latest_used_by_network = {}  # network_name -> migrated_at epoch
        cex_label_by_network = {}  # network_name -> str|None
        try:
            conn, cursor = get_db_conn()

            # All network memberships in one query
            cursor.execute("SELECT network_name, creator_address FROM network_membership")
            for row in cursor.fetchall():
                creators_by_network.setdefault(row['network_name'], []).append(row['creator_address'])

            # All creator→token counts in one query, then aggregate per network
            all_creators = [c for lst in creators_by_network.values() for c in lst]
            if all_creators:
                ph = ','.join('?' * len(all_creators))
                cursor.execute(f"""
                    SELECT
                        earliest_tx_creator,
                        COUNT(DISTINCT mint) AS cnt,
                        MAX(CASE WHEN migrated_at IS NOT NULL THEN migrated_at ELSE 0 END) AS latest_used_at
                    FROM token_analysis
                    WHERE earliest_tx_creator IN ({ph})
                    GROUP BY earliest_tx_creator
                """, all_creators)
                token_rows = cursor.fetchall()
                tokens_per_creator = {row['earliest_tx_creator']: row['cnt'] for row in token_rows}
                latest_per_creator = {row['earliest_tx_creator']: row['latest_used_at'] or 0 for row in token_rows}
                for net_name, creators in creators_by_network.items():
                    token_count_by_network[net_name] = sum(tokens_per_creator.get(c, 0) for c in creators)
                    latest_used_by_network[net_name] = max((latest_per_creator.get(c, 0) for c in creators), default=0)

            # CEX labels: one query for first member of each CEX network
            cex_networks = [n['network_name'] for n in all_networks if n.get('has_cex_funder')]
            if cex_networks:
                for net_name in cex_networks:
                    first_creator = (creators_by_network.get(net_name) or [None])[0]
                    if first_creator:
                        cex_label_by_network[net_name] = get_cex_infra_label(first_creator)

            conn.close()
        except Exception as e:
            print(f"[DEBUG] Error in bulk network stats fetch: {e}")

        for network in all_networks:
            network_name = network['network_name']
            network_size = network['network_size']
            funder_is_cex = network['has_cex_funder']

            creators_funded = len(creators_by_network.get(network_name, []))
            token_count = token_count_by_network.get(network_name, 0)
            latest_used_at = latest_used_by_network.get(network_name, 0)
            sol_amount = 0.0
            cex_label = cex_label_by_network.get(network_name)

            total_tokens += token_count
            total_creators_funded += creators_funded
            total_sol += sol_amount

            # Get score information
            score_info = scores_map.get(network_name)

            networks.append({
                'name': network_name,
                'display_name': network.get('display_name') or network_name.replace('_', '-'),
                'display_name_reason': network.get('display_name_reason'),
                'display_name_source': network.get('display_name_source'),
                'tier': network.get('network_type', 'N/A'),
                'is_cex': funder_is_cex,
                'cex_label': cex_label,
                'network_size': network_size,
                'token_count': token_count,
                'latest_used_at': latest_used_at,
                'latest_used_label': datetime.fromtimestamp(latest_used_at).strftime('%d %b') if latest_used_at else '—',
                'creators_funded': creators_funded,
                'sol_amount': sol_amount,
                'score': score_info['score'] if score_info else None,
                'score_badge': 'high' if (score_info and score_info['score'] >= 70) else ('medium' if (score_info and score_info['score'] >= 30) else 'low') if score_info else None,
                'second_hop_bridge_count': network.get('second_hop_bridge_count', 0) or 0,
                'max_second_hop_confidence': network.get('max_second_hop_confidence', 0) or 0,
            })

        networks.sort(key=lambda n: n.get('latest_used_at') or 0, reverse=True)

        return {
            'networks': networks,
            'total_tokens': total_tokens,
            'total_creators_funded': total_creators_funded,
            'total_sol': total_sol,
            'total_networks': len(networks)
        }, 200

    def legacy_path():

        """OLD PATH: Use legacy atomic_network_names"""
        conn = db_connect(DB_PATH, timeout=5)
        conn.row_factory = sqlite3.Row
        conn.execute("PRAGMA query_only = ON")
        cursor = conn.cursor()

        # Get all atomic networks with token stats
        cursor.execute("""
            SELECT
                ann.funder_address,
                ann.network_name,
                ann.network_tier,
                ann.is_cex,
                (CASE WHEN ann.funder_address IN (SELECT cex_address FROM cex_wallets WHERE is_active = 1) THEN 1 ELSE 0 END) as funder_is_cex,
                COUNT(DISTINCT ta.mint) as token_count,
                COUNT(DISTINCT cf.creator_address) as creators_funded,
                ROUND(SUM(cf.amount_sol), 2) as total_sol
            FROM atomic_network_names ann
            LEFT JOIN creator_funders cf ON ann.funder_address = cf.funder_address
            LEFT JOIN token_analysis ta ON cf.creator_address = ta.earliest_tx_creator
            GROUP BY ann.funder_address, ann.network_name, ann.network_tier, ann.is_cex
            HAVING creators_funded >= 2
            ORDER BY
                CASE
                    WHEN ann.network_tier = 'Apex' THEN 1
                    WHEN ann.network_tier = 'Nexus' THEN 2
                    WHEN ann.network_tier = 'Relay' THEN 3
                    WHEN ann.network_tier = 'Node' THEN 4
                    WHEN ann.network_tier = 'Exchange' THEN 5
                END,
                token_count DESC
        """)

        networks = []
        total_tokens = 0
        total_creators = 0
        total_creators_funded = 0
        total_sol = 0.0
        total_networks = 0
        all_rows = list(cursor.fetchall())

        # Batch fetch scores for all networks (using JOIN for better scalability)
        scores_map = {}
        try:
            cursor.execute('DROP TABLE IF EXISTS temp_networks_legacy')
            cursor.execute('CREATE TEMP TABLE temp_networks_legacy (network_name TEXT PRIMARY KEY)')

            # Insert all network names from rows
            for row in all_rows:
                cursor.execute('INSERT INTO temp_networks_legacy (network_name) VALUES (?)',
                             (row['network_name'],))

            # Join with network_scores to fetch scores efficiently
            cursor.execute('''
                SELECT tnl.network_name, ns.score
                FROM temp_networks_legacy tnl
                LEFT JOIN network_scores ns USING (network_name)
            ''')

            for score_row in cursor.fetchall():
                if score_row['score'] is not None:  # Only add if score exists
                    scores_map[score_row['network_name']] = {
                        'score': score_row['score'],
                        'components': {}
                    }

            cursor.execute('DROP TABLE IF EXISTS temp_networks_legacy')
        except Exception as e:
            print(f"[DEBUG] Error fetching network scores in legacy path: {e}")

        for row in all_rows:
            network_name = row['network_name']
            tier = row['network_tier']
            funder_address = row['funder_address']
            token_count = int(row['token_count'] or 0)
            creators_funded = int(row['creators_funded'] or 0)
            sol_amount = float(row['total_sol'] or 0.0)
            funder_is_cex = bool(row['funder_is_cex'])

            total_tokens += token_count
            total_creators_funded += creators_funded
            total_sol += sol_amount
            total_networks += 1

            # Get CEX/INFRA label if this is a CEX/INFRA funder
            cex_label = get_cex_infra_label(funder_address) if funder_is_cex else None

            # Get score information
            score_info = scores_map.get(network_name)

            networks.append({
                'name': network_name,
                'tier': tier,
                'is_cex': funder_is_cex,
                'cex_label': cex_label,
                'token_count': token_count,
                'latest_used_at': 0,
                'latest_used_label': '—',
                'creators_funded': creators_funded,
                'sol_amount': sol_amount,
                'score': score_info['score'] if score_info else None,
                'score_badge': 'high' if (score_info and score_info['score'] >= 70) else ('medium' if (score_info and score_info['score'] >= 30) else 'low') if score_info else None
            })

        conn.close()

        return {
            'networks': networks,
            'total_tokens': total_tokens,
            'total_creators_funded': total_creators_funded,
            'total_sol': total_sol,
            'total_networks': total_networks
        }, 200

    # Call the router to get the context
    response, status_code = route_phase2c('/networks', new_path, legacy_path)

    # Extract context from response
    if status_code == 200:
        if isinstance(response, str):
            return response, status_code
        # If it came from jsonify, extract the data
        import json as json_module
        context = json.loads(response.get_data(as_text=True))
    else:
        return response, status_code

    networks = context['networks']
    total_tokens = context['total_tokens']
    total_creators_funded = context['total_creators_funded']
    total_sol = context['total_sol']
    total_networks = context['total_networks']

    # Cross-system enrichment: add farm_cluster and coordinator context per network
    try:
        from src.core.unified_network_intelligence import network_cross_links, system_freshness
        _conn = db_connect(DB_PATH, timeout=10)
        _conn.row_factory = sqlite3.Row
        net_names = [n['name'] for n in networks]
        cross = network_cross_links(_conn, net_names)
        freshness = system_freshness(_conn)
        _conn.close()
        for n in networks:
            xl = cross.get(n['name'], {})
            n['farm_cluster_ids']     = xl.get('farm_cluster_ids', [])
            n['coordinator_wallets']  = xl.get('coordinator_wallets', [])
    except Exception as _xe:
        logger.warning(f"Network cross-links skipped: {_xe}")
        freshness = {}

    return render_template(
        "networks_dashboard.html",
        networks=networks,
        total_networks=total_networks,
        total_creators_funded=total_creators_funded,
        total_tokens=total_tokens,
        total_sol=total_sol,
        freshness=freshness,
        active_page="networks"
    )


@app.route('/top-funding-hubs')
def top_funding_hubs():
    """Display dashboard of all top funding hubs (duplicate senders)"""
    try:
        from src.core.token_behavior import compute_token_class
        from src.utils.infra_mapping import get_account_info, get_cex_info

        conn = db_connect(DB_PATH, timeout=15)
        conn.row_factory = sqlite3.Row
        c = conn.cursor()
        c.execute("SELECT name FROM sqlite_master WHERE type='table'")
        table_names = {table_row["name"] for table_row in c.fetchall()}

        def _short_addr(address):
            if not address:
                return "unknown"
            return f"{address[:8]}...{address[-4:]}" if len(address) > 14 else address

        def _format_money(value):
            value = float(value or 0)
            if value <= 0:
                return "—"
            if value >= 1_000_000:
                return f"${value / 1_000_000:.2f}M"
            if value >= 1_000:
                return f"${value / 1_000:.1f}K"
            return f"${value:.0f}"

        def _format_sol(value):
            value = float(value or 0)
            if value >= 10:
                return f"{value:.2f} SOL"
            return f"{value:.4f}".rstrip("0").rstrip(".") + " SOL"

        def _parse_ts(value):
            if value in (None, ""):
                return None
            try:
                if isinstance(value, (int, float)):
                    ts = int(value)
                    return ts if ts > 0 else None
                raw = str(value).strip()
                if raw.isdigit():
                    ts = int(raw)
                    return ts if ts > 0 else None
                raw = raw.replace("Z", "+00:00")
                return int(datetime.fromisoformat(raw).timestamp())
            except Exception:
                return None

        def _format_date(value):
            ts = _parse_ts(value)
            if not ts:
                return "—"
            return datetime.fromtimestamp(ts).strftime("%d %b")

        def _get_hub_label(address):
            if not address:
                return {
                    "name": "Unknown",
                    "type": "Unknown",
                    "category": "unknown",
                    "description": None,
                }

            infra_info = get_account_info(address)
            if infra_info:
                return {
                    "name": infra_info.get("name") or "Infrastructure",
                    "type": "INFRA",
                    "category": infra_info.get("category") or "infra",
                    "description": infra_info.get("description"),
                }

            cex_info = get_cex_info(address)
            if cex_info:
                return {
                    "name": cex_info.get("name") or cex_info.get("exchange") or "CEX",
                    "type": "CEX",
                    "category": cex_info.get("category") or "cex",
                    "description": cex_info.get("description"),
                }

            c.execute("""
                SELECT exchange_name, wallet_type
                FROM cex_wallets
                WHERE cex_address = ? AND is_active = 1
                LIMIT 1
            """, (address,))
            row = c.fetchone()
            if row:
                wallet_type = row["wallet_type"] or "wallet"
                exchange_name = row["exchange_name"] or "CEX"
                name = exchange_name if wallet_type in ("Hot Wallet", "Exchange Wallet") else f"{exchange_name} {wallet_type}"
                return {
                    "name": name,
                    "type": "CEX",
                    "category": wallet_type,
                    "description": None,
                }

            c.execute("""
                SELECT sender_type, cex_exchange, cex_type
                FROM funder_incoming_transfers
                WHERE sender_address = ?
                  AND (sender_type IS NOT NULL OR cex_exchange IS NOT NULL OR cex_type IS NOT NULL)
                LIMIT 1
            """, (address,))
            row = c.fetchone()
            if row:
                sender_type = (row["sender_type"] or "").lower()
                if row["cex_exchange"] or sender_type == "cex":
                    return {
                        "name": row["cex_exchange"] or "Detected CEX",
                        "type": "CEX",
                        "category": row["cex_type"] or "cex",
                        "description": None,
                    }
                if sender_type == "infra":
                    return {
                        "name": "Detected Infrastructure",
                        "type": "INFRA",
                        "category": "infra",
                        "description": None,
                    }

            return {
                "name": "Unlabeled",
                "type": "Unknown",
                "category": "unknown",
                "description": None,
            }

        def _median(values):
            values = sorted(float(v or 0) for v in values)
            if not values:
                return 0
            mid = len(values) // 2
            if len(values) % 2:
                return values[mid]
            return (values[mid - 1] + values[mid]) / 2

        # Get top 20 senders by number of funders they send to
        c.execute("""
            SELECT
                sender_address,
                COUNT(DISTINCT funder_address) as funder_count,
                SUM(amount_sol) as total_sol_sent,
                MIN(amount_sol) as min_sol_sent,
                MAX(amount_sol) as max_sol_sent,
                MAX(COALESCE(
                    NULLIF(block_time, 0),
                    CAST(strftime('%s', first_detected_at) AS INTEGER)
                )) as latest_transfer_at
            FROM funder_incoming_transfers
            GROUP BY sender_address
            ORDER BY funder_count DESC
            LIMIT 50
        """)
        hubs = []
        for row in c.fetchall():
            sender_addr = row["sender_address"]
            funder_count = row["funder_count"]
            total_sol = row["total_sol_sent"] or 0

            # Count creators funded by those funders
            c.execute("""
                SELECT COUNT(DISTINCT creator_address) FROM creator_funders
                WHERE funder_address IN (
                    SELECT DISTINCT funder_address FROM funder_incoming_transfers
                    WHERE sender_address = ?
                )
            """, (sender_addr,))
            creator_count = c.fetchone()[0]

            # Count tokens created by those creators
            c.execute("""
                SELECT COUNT(*) FROM token_analysis
                WHERE earliest_tx_creator IN (
                    SELECT DISTINCT creator_address FROM creator_funders
                    WHERE funder_address IN (
                        SELECT DISTINCT funder_address FROM funder_incoming_transfers
                        WHERE sender_address = ?
                    )
                )
            """, (sender_addr,))
            token_count = c.fetchone()[0]

            # Check if this sender is also a creator
            c.execute("""
                SELECT COUNT(*) FROM token_analysis
                WHERE earliest_tx_creator = ?
            """, (sender_addr,))
            created_tokens = c.fetchone()[0]

            # Check for self-funding (funders that only fund the sender back)
            c.execute("""
                SELECT COUNT(DISTINCT funder_address)
                FROM funder_incoming_transfers
                WHERE sender_address = ?
                AND funder_address IN (
                    SELECT funder_address FROM creator_funders
                    WHERE creator_address = ?
                )
            """, (sender_addr, sender_addr))
            self_funding_count = c.fetchone()[0]

            # If all creators are the sender itself, mark as self-funding
            is_likely_self_funded = creator_count == 1 and created_tokens > 0

            c.execute("""
                SELECT COUNT(DISTINCT creator_address)
                FROM creator_funders
                WHERE funder_address = ?
            """, (sender_addr,))
            direct_creator_count = c.fetchone()[0] or 0

            c.execute("""
                SELECT
                    COUNT(DISTINCT fnm.network_name) AS network_count,
                    GROUP_CONCAT(DISTINCT fnm.network_name) AS networks
                FROM funder_incoming_transfers fit
                JOIN funder_network_map fnm ON fnm.funder_address = fit.funder_address
                WHERE fit.sender_address = ?
            """, (sender_addr,))
            network_row = c.fetchone()
            networks = sorted((network_row["networks"] or "").split(",")) if network_row and network_row["networks"] else []

            approval_counts = {"approved": 0, "pending": 0, "rejected": 0, "needs_evidence": 0}
            if networks and "network_review_status" in table_names:
                placeholders = ",".join("?" * len(networks))
                c.execute(f"""
                    SELECT COALESCE(nrs.status, 'pending') AS status, COUNT(*) AS count
                    FROM (
                        SELECT network_name
                        FROM networks_release
                        WHERE network_name IN ({placeholders})
                    ) nr
                    LEFT JOIN network_review_status nrs ON nrs.network_name = nr.network_name
                    GROUP BY COALESCE(nrs.status, 'pending')
                """, networks)
                for status_row in c.fetchall():
                    approval_counts[status_row["status"]] = status_row["count"]

            c.execute("""
                SELECT amount_sol
                FROM funder_incoming_transfers
                WHERE sender_address = ?
            """, (sender_addr,))
            sent_amounts = [amount_row["amount_sol"] for amount_row in c.fetchall()]

            c.execute("""
                SELECT
                    COUNT(*) AS tracked_count,
                    SUM(CASE WHEN COALESCE(ta.lifecycle_stage, '') = 'migrated' AND ta.migrated_at IS NOT NULL THEN 1 ELSE 0 END) AS migrated_count,
                    SUM(CASE WHEN NOT (COALESCE(ta.lifecycle_stage, '') = 'migrated' AND ta.migrated_at IS NOT NULL) THEN 1 ELSE 0 END) AS bonding_count,
                    MAX(COALESCE(ta.market_cap_highest, ta.market_cap_current, 0)) AS best_peak_mc,
                    MAX(COALESCE(
                        NULLIF(ta.migrated_at, 0),
                        NULLIF(ta.market_cap_highest_at_ts, 0),
                        CASE
                            WHEN CAST(ta.created_at AS REAL) > 1000000000 THEN CAST(ta.created_at AS INTEGER)
                            ELSE CAST(strftime('%s', ta.created_at) AS INTEGER)
                        END
                    )) AS latest_token_at
                FROM token_analysis ta
                WHERE ta.earliest_tx_creator IN (
                    SELECT DISTINCT cf.creator_address
                    FROM creator_funders cf
                    WHERE cf.funder_address IN (
                        SELECT DISTINCT fit.funder_address
                        FROM funder_incoming_transfers fit
                        WHERE fit.sender_address = ?
                    )
                )
            """, (sender_addr,))
            token_stats = c.fetchone()
            tracked_count = token_stats["tracked_count"] or 0
            migrated_count = token_stats["migrated_count"] or 0
            bonding_count = token_stats["bonding_count"] or 0
            best_peak_mc = token_stats["best_peak_mc"] or 0
            best_g = compute_token_class(best_peak_mc) if best_peak_mc else "—"
            latest_activity_at = max(
                _parse_ts(row["latest_transfer_at"]) or 0,
                _parse_ts(token_stats["latest_token_at"] if token_stats else None) or 0,
            )

            jito_row = None
            if "creator_service_history" in table_names:
                c.execute("""
                    SELECT
                        ROUND(csh.amount_sol, 9) AS amount_sol,
                        CASE
                            WHEN csh.tag = 'uses_jitotip' THEN 'Create'
                            ELSE COALESCE(csh.tx_type, 'Other')
                        END AS tx_type,
                        COUNT(*) AS event_count,
                        COUNT(DISTINCT csh.creator_address) AS creator_count
                    FROM creator_service_history csh
                    WHERE csh.tag IN ('uses_jitotip', 'uses_jitotip_other')
                      AND COALESCE(csh.amount_sol, 0) > 0
                      AND csh.creator_address IN (
                          SELECT DISTINCT cf.creator_address
                          FROM creator_funders cf
                          WHERE cf.funder_address IN (
                              SELECT DISTINCT fit.funder_address
                              FROM funder_incoming_transfers fit
                              WHERE fit.sender_address = ?
                          )
                      )
                    GROUP BY ROUND(csh.amount_sol, 9), tx_type
                    HAVING creator_count >= 2
                    ORDER BY creator_count DESC, event_count DESC
                    LIMIT 1
                """, (sender_addr,))
                jito_row = c.fetchone()

            label = _get_hub_label(sender_addr)
            role = "Upstream"
            if direct_creator_count and funder_count:
                role = "Direct + Upstream"
            elif direct_creator_count:
                role = "Direct"

            hubs.append({
                'address': sender_addr,
                'short_address': _short_addr(sender_addr),
                'label': label,
                'role': role,
                'funder_count': funder_count,
                'creator_count': creator_count,
                'direct_creator_count': direct_creator_count,
                'total_sol_sent': total_sol or 0,
                'total_sol_display': _format_sol(total_sol),
                'min_sol_display': _format_sol(row["min_sol_sent"]),
                'max_sol_display': _format_sol(row["max_sol_sent"]),
                'median_sol_display': _format_sol(_median(sent_amounts)),
                'token_count': token_count,
                'tracked_count': tracked_count,
                'migrated_count': migrated_count,
                'bonding_count': bonding_count,
                'network_count': network_row["network_count"] if network_row else 0,
                'sample_networks': networks[:4],
                'approval_counts': approval_counts,
                'best_peak_mc': best_peak_mc,
                'best_peak_display': _format_money(best_peak_mc),
                'best_g': best_g,
                'latest_seen_at': latest_activity_at,
                'latest_seen_display': _format_date(latest_activity_at),
                'jito_pattern': {
                    'amount_sol': _format_sol(jito_row["amount_sol"]),
                    'tx_type': jito_row["tx_type"],
                    'creator_count': jito_row["creator_count"],
                    'event_count': jito_row["event_count"],
                } if jito_row else None,
                'created_tokens': created_tokens,
                'self_funding_count': self_funding_count,
                'is_likely_self_funded': is_likely_self_funded
            })

        conn.close()
        hubs.sort(key=lambda hub: hub.get('latest_seen_at') or 0, reverse=True)
        hubs = hubs[:20]

        return render_template(
            'top_funding_hubs.html',
            active_page='hubs',
            hubs=list(enumerate(hubs, 1)),
        )

    except Exception as e:
        return f"<html><body style='background:#0a0a0e; color: red;'><h1>Error</h1><p>{str(e)}</p></body></html>", 500


@app.route('/funding-hub/<hub_address>')
def funding_hub(hub_address):
    """Display funding hub network: sender -> funders -> creators -> tokens, OR funder -> creators -> tokens"""
    try:
        conn = db_connect(DB_PATH, timeout=15)
        c = conn.cursor()

        # Determine if this address is a sender or a funder
        c.execute("SELECT COUNT(*) FROM token_analysis WHERE earliest_tx_creator = ?", (hub_address,))
        sender_token_count = c.fetchone()[0]

        # Check if address is a funder (funds multiple creators)
        c.execute("SELECT COUNT(DISTINCT creator_address) FROM creator_funders WHERE funder_address = ?", (hub_address,))
        funder_creator_count = c.fetchone()[0]

        # Check if address is a sender (has funders in funder_incoming_transfers)
        c.execute("""
            SELECT COUNT(DISTINCT funder_address)
            FROM funder_incoming_transfers
            WHERE sender_address = ?
        """, (hub_address,))
        sender_funder_count = c.fetchone()[0]

        funder_data = []
        self_funding_funders = 0
        third_party_funded_creators = set()
        hub_type = None  # 'sender' or 'funder'

        # CASE 1: Address is a sender (original case)
        if sender_funder_count > 0:
            hub_type = 'sender'
            # Get all funders that received from this sender
            c.execute("""
                SELECT DISTINCT funder_address
                FROM funder_incoming_transfers
                WHERE sender_address = ?
            """, (hub_address,))
            receiving_funders = [row[0] for row in c.fetchall()]

            for funder in receiving_funders:
                c.execute("""
                    SELECT DISTINCT creator_address
                    FROM creator_funders
                    WHERE funder_address = ?
                """, (funder,))
                funded_creators = [row[0] for row in c.fetchall()]

                # Check if this funder only funds the sender (self-funding)
                is_self_funding = len(funded_creators) == 1 and funded_creators[0] == hub_address
                if is_self_funding:
                    self_funding_funders += 1
                    continue

                # Count tokens for those creators
                creator_list = ','.join(['?' for _ in funded_creators])
                if funded_creators:
                    c.execute(f"""
                        SELECT COUNT(*) FROM token_analysis
                        WHERE earliest_tx_creator IN ({creator_list})
                    """, funded_creators)
                    token_count = c.fetchone()[0]
                    for creator in funded_creators:
                        third_party_funded_creators.add(creator)
                else:
                    token_count = 0

                # Check if this funder is a multi-creator funder (coordinated funder)
                c.execute("""
                    SELECT funder_address FROM coordinated_funders
                    WHERE funder_address = ?
                """, (funder,))
                coordinated_result = c.fetchone()
                is_multi_creator_funder = coordinated_result is not None

                funder_data.append({
                    'address': funder,
                    'creator_count': len(funded_creators),
                    'token_count': token_count,
                    'sample_creators': funded_creators[:5],
                    'is_multi_creator_funder': is_multi_creator_funder
                })

        # CASE 2: Address is a funder (funds creators directly)
        elif funder_creator_count > 0:
            hub_type = 'funder'
            # Get all creators funded by this address with their token counts
            c.execute("""
                SELECT DISTINCT creator_address
                FROM creator_funders
                WHERE funder_address = ?
            """, (hub_address,))
            funded_creators = [row[0] for row in c.fetchall()]

            # For each creator, get token count
            for creator in funded_creators:
                c.execute("""
                    SELECT COUNT(*) FROM token_analysis
                    WHERE earliest_tx_creator = ?
                """, (creator,))
                creator_token_count = c.fetchone()[0]

                third_party_funded_creators.add(creator)

                funder_data.append({
                    'address': creator,
                    'creator_count': 1,  # This is a creator, not a funder
                    'token_count': creator_token_count,
                    'sample_creators': [creator],
                    'is_creator': True
                })

        # Fetch all tokens for funded creators
        tokens_data = []
        if third_party_funded_creators:
            creator_list = list(third_party_funded_creators)
            placeholders = ','.join('?' * len(creator_list))
            c.execute(f"""
                SELECT
                    ta.mint,
                    tt.symbol,
                    ta.earliest_tx_creator,
                    ta.lifecycle_stage,
                    ta.market_cap_highest,
                    ta.market_cap_current,
                    ta.created_at,
                    ta.migrated_at
                FROM token_analysis ta
                LEFT JOIN tracked_tokens tt ON tt.mint = ta.mint
                WHERE ta.earliest_tx_creator IN ({placeholders})
                ORDER BY ta.market_cap_highest DESC NULLS LAST
            """, creator_list)
            for row in c.fetchall():
                tokens_data.append({
                    'mint': row[0],
                    'symbol': row[1] or '—',
                    'creator': row[2],
                    'stage': row[3] or '—',
                    'peak_mc': row[4],
                    'current_mc': row[5],
                    'created_at': row[6],
                    'migrated_at': row[7],
                })
            bonding_curve_count = sum(1 for t in tokens_data if t['stage'] == 'bonding_curve')
            pending_count = sum(1 for t in tokens_data if t['stage'] == 'migration_pending')
            bonded_only_count = bonding_curve_count
            pending_only_count = pending_count
            tokens_data = [t for t in tokens_data if t['stage'] == 'migrated']
        else:
            bonded_only_count = 0
            pending_only_count = 0

        conn.close()

        # Sort by token count descending
        funder_data.sort(key=lambda x: x['token_count'], reverse=True)

        html = """
        <!DOCTYPE html>
        <html>
        <head>
            <title>Funding Hub: """ + hub_address + """</title>
            <style>
                :root {
                    --color-purple: #a78bfa;
                    --color-cyan: #06b6d4;
                    --color-green: #16a34a;
                    --color-yellow: #fbbf24;
                    --text-primary: #e5e7eb;
                    --text-secondary: #9ca3af;
                    --bg-dark: linear-gradient(135deg, #0a0a0e 0%, #0d0d15 100%);
                    --bg-card: rgba(30, 30, 40, 0.8);
                    --bg-hover: rgba(167, 139, 250, 0.05);
                    --border-color: rgba(167, 139, 250, 0.3);
                    --blue: #3b82f6;
                }

                * {
                    margin: 0;
                    padding: 0;
                    box-sizing: border-box;
                }

                body {
                    background: var(--bg-dark);
                    color: var(--text-primary);
                    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, monospace;
                    padding: 30px;
                }

                .container {
                    max-width: 1200px;
                    margin: 0 auto;
                }

                h1 {
                    color: var(--color-purple);
                    margin-bottom: 8px;
                    font-size: 28px;
                }

                h2 {
                    color: var(--color-purple);
                }

                .hub-address {
                    font-family: monospace;
                    font-size: 12px;
                    color: var(--text-secondary);
                    margin-bottom: 24px;
                    word-break: break-all;
                }

                .stats {
                    display: grid;
                    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
                    gap: 16px;
                    margin-bottom: 32px;
                }

                .stat-box {
                    background: var(--bg-card);
                    border: 1px solid var(--border-color);
                    border-radius: 8px;
                    padding: 16px;
                }

                .stat-box.hub {
                    border-left: 3px solid rgba(167, 139, 250, 0.5);
                }

                .stat-label {
                    font-size: 11px;
                    color: var(--text-secondary);
                    text-transform: uppercase;
                    margin-bottom: 8px;
                }

                .stat-value {
                    font-size: 24px;
                    font-weight: bold;
                    color: var(--color-purple);
                }

                table {
                    width: 100%;
                    border-collapse: collapse;
                    background: var(--bg-card);
                    border: 1px solid var(--border-color);
                    border-radius: 8px;
                    overflow: hidden;
                }

                thead {
                    background: var(--bg-card);
                    border-bottom: 2px solid var(--border-color);
                    border-left: 3px solid rgba(167, 139, 250, 0.5);
                }

                th {
                    padding: 15px;
                    text-align: left;
                    color: var(--color-purple);
                    font-weight: 600;
                    font-size: 13px;
                    text-transform: uppercase;
                }

                td {
                    padding: 15px;
                    border-bottom: 1px solid rgba(167, 139, 250, 0.2);
                    font-size: 13px;
                }

                tr:last-child td {
                    border-bottom: none;
                }

                tbody tr:hover {
                    background: var(--bg-hover);
                }

                .address {
                    font-family: monospace;
                    font-size: 11px;
                    color: var(--blue);
                    word-break: break-all;
                    cursor: pointer;
                }

                .address:hover {
                    color: var(--color-purple);
                    text-decoration: underline;
                }

                .stat-number {
                    font-weight: bold;
                    color: var(--color-green);
                }

                .back-link {
                    display: inline-block;
                    margin-bottom: 20px;
                    color: var(--color-cyan);
                    text-decoration: none;
                    font-size: 13px;
                }

                .back-link:hover {
                    color: var(--color-purple);
                    text-decoration: underline;
                }
            </style>
        </head>
        <body>
            <div class="container">
                <a href="/top-funding-hubs" class="back-link">← Back to Hubs</a>

                <h1>""" + ("🔗 Multi-Creator Funder" if hub_type == 'funder' else "💰 Funding Distribution Sender") + """</h1>
                <div class="hub-address">""" + hub_address + """</div>

                <div class="stats">
        """

        if hub_type == 'sender':
            html += f"""
                    <div class="stat-box hub">
                        <div class="stat-label">Tokens Created by Sender</div>
                        <div class="stat-value">{sender_token_count}</div>
                    </div>
                    <div class="stat-box hub" style="border-left: 3px solid rgba(239, 68, 68, 0.5); background: rgba(239, 68, 68, 0.08);">
                        <div class="stat-label">⚠️ Self-Funding Intermediates</div>
                        <div class="stat-value" style="color: #ef4444;">{self_funding_funders}</div>
                        <div class="stat-label" style="margin-top: 8px; font-size: 11px; color: #ef4444;">Fund sender only</div>
                    </div>
                    <div class="stat-box hub">
                        <div class="stat-label">Third-Party Funded Creators</div>
                        <div class="stat-value">{len(third_party_funded_creators)}</div>
                    </div>
                    <div class="stat-box hub">
                        <div class="stat-label">Tokens from Third-Party Creators</div>
                        <div class="stat-value">{sum(f['token_count'] for f in funder_data)}</div>
                    </div>
                    <div class="stat-box hub" style="border-left: 3px solid rgba(251, 146, 60, 0.5); background: rgba(251, 146, 60, 0.08);">
                        <div class="stat-label">🔗 Multi-Creator Funders</div>
                        <div class="stat-value" style="color: #fb923c;">{sum(1 for f in funder_data if f.get('is_multi_creator_funder'))}</div>
                        <div class="stat-label" style="margin-top: 8px; font-size: 11px; color: #fb923c;">Fund multiple creators</div>
                    </div>
            """
        else:  # funder
            html += f"""
                    <div class="stat-box hub">
                        <div class="stat-label">Creators Funded</div>
                        <div class="stat-value">{funder_creator_count}</div>
                    </div>
                    <div class="stat-box hub">
                        <div class="stat-label">Tokens Launched</div>
                        <div class="stat-value">{sum(f['token_count'] for f in funder_data)}</div>
                    </div>
                    <div class="stat-box hub">
                        <div class="stat-label">Multi-Creator Funder</div>
                        <div class="stat-value" style="color: var(--color-yellow);">⚠️ YES</div>
                    </div>
            """

        html += """
                </div>

                <h2 style="margin-bottom: 16px; font-size: 18px;">""" + ("Creators Funded" if hub_type == 'funder' else "Third-Party Funders (Fund Other Creators)") + """</h2>
                <p style="color: #94a3b8; margin-bottom: 16px; font-size: 13px;">""" + ("Creators funded by this address and their tokens" if hub_type == 'funder' else "Showing funders that fund creators OTHER than this sender. Self-funding intermediaries are excluded.") + """</p>
                <table>
                    <thead>
                        <tr>
                            <th>""" + ("Creator Address" if hub_type == 'funder' else "Funder Address") + """</th>
                            <th style="text-align: center;">""" + ("Tokens Launched" if hub_type == 'funder' else "Creators Funded") + """</th>
                            <th style="text-align: center;">""" + ("Funding Source" if hub_type == 'funder' else "Tokens Launched") + """</th>
                            <th>""" + ("Network Info" if hub_type == 'funder' else "Sample Creators") + """</th>
                        </tr>
                    </thead>
                    <tbody>
        """

        if len(funder_data) == 0:
            # Empty state message
            if hub_type == 'sender':
                html += """
                        <tr>
                            <td colspan="4" style="text-align: center; padding: 40px; color: #94a3b8;">
                                <p style="margin: 0; font-size: 14px;">ℹ️ No third-party funders found</p>
                                <p style="margin: 8px 0 0 0; font-size: 12px; color: #64748b;">All funders are self-funding intermediaries (fund sender only)</p>
                            </td>
                        </tr>
                """
            else:
                html += """
                        <tr>
                            <td colspan="4" style="text-align: center; padding: 40px; color: #94a3b8;">
                                <p style="margin: 0; font-size: 14px;">ℹ️ No creators funded</p>
                            </td>
                        </tr>
                """
        else:
            for funder in funder_data:
                sample_creators = ', '.join([addr[:8] + '...' for addr in funder['sample_creators']])
                if hub_type == 'funder':
                    # For funder type, show the creator entry directly
                    html += f"""
                            <tr>
                                <td><span class="address">{funder['address']}</span></td>
                                <td style="text-align: center;"><span class="stat-number">{funder['token_count']}</span></td>
                                <td style="text-align: center;"><span style="color: var(--color-yellow); font-weight: 600;">Multi-Creator</span></td>
                                <td><small style="color: #94a3b8;">Funded by {hub_address[:8]}...</small></td>
                            </tr>
                    """
                else:
                    # For sender type, show funder entries with multi-funder indicator
                    multi_funder_badge = ""
                    if funder.get('is_multi_creator_funder'):
                        multi_funder_badge = ' <span style="background: rgba(251, 146, 60, 0.3); color: #fb923c; padding: 2px 6px; border-radius: 3px; font-size: 10px; font-weight: 600; margin-left: 4px;">🔗 Multi-Funder</span>'

                    html += f"""
                            <tr>
                                <td><span class="address">{funder['address']}</span>{multi_funder_badge}</td>
                                <td style="text-align: center;"><span class="stat-number">{funder['creator_count']}</span></td>
                                <td style="text-align: center;"><span class="stat-number">{funder['token_count']}</span></td>
                                <td><small style="color: #94a3b8;">{sample_creators if sample_creators else 'N/A'}</small></td>
                            </tr>
                    """

        html += """
                    </tbody>
                </table>
        """

        # ── Tokens table ──────────────────────────────────────────────────────
        extra_notes = ''
        if bonded_only_count:
            extra_notes += f' &nbsp;·&nbsp; <span style="color:#f97316;">{bonded_only_count} bonding curve</span>'
        if pending_only_count:
            extra_notes += f' &nbsp;·&nbsp; <span style="color:#fbbf24;">{pending_only_count} pending</span>'
        html += f"""
                <h2 style="margin: 36px 0 8px; font-size: 18px;">Graduated Tokens</h2>
                <p style="color: #94a3b8; margin-bottom: 16px; font-size: 13px;">
                    <span style="color: #22c55e;">{len(tokens_data)} graduated</span>{extra_notes}
                </p>
                <table>
                    <thead>
                        <tr>
                            <th>#</th>
                            <th>Symbol</th>
                            <th>Mint</th>
                            <th>Creator</th>
                            <th style="text-align:center;" title="G-class: peak market cap tier. G1=Elite(5M+) G2=Strong(2–5M) G3=High Opp(500K–2M) G4=Pre-Runner(300–500K) G5=Mid(150–300K) G6=Weak(75–150K) G7=Low(<75K)">G</th>
                            <th style="text-align:right;">Peak MC</th>
                            <th style="text-align:right;">Current MC</th>
                        </tr>
                    </thead>
                    <tbody>
        """

        G_COLOR = {'G1':'#f59e0b','G2':'#a78bfa','G3':'#60a5fa','G4':'#34d399','G5':'#86efac','G6':'#6b7280','G7':'#374151'}
        G_BG    = {'G1':'rgba(245,158,11,0.12)','G2':'rgba(167,139,250,0.12)','G3':'rgba(96,165,250,0.12)','G4':'rgba(52,211,153,0.12)','G5':'rgba(134,239,172,0.08)','G6':'rgba(107,114,128,0.10)','G7':'rgba(55,65,81,0.10)'}
        G_TIP   = {'G1':'Elite (5M+)','G2':'Strong (2–5M)','G3':'High Opportunity (500K–2M)','G4':'Pre-Runner (300–500K)','G5':'Mid Tier (150–300K)','G6':'Weak (75–150K)','G7':'Low / Noise (<75K)'}

        def _g_class(mc):
            if mc is None: return None
            if mc >= 5_000_000: return 'G1'
            if mc >= 2_000_000: return 'G2'
            if mc >= 500_000:   return 'G3'
            if mc >= 300_000:   return 'G4'
            if mc >= 150_000:   return 'G5'
            if mc >= 75_000:    return 'G6'
            return 'G7'

        def _g_badge(mc):
            g = _g_class(mc)
            if not g: return '<span style="color:#4b5563;">—</span>'
            return (f'<span style="background:{G_BG[g]};color:{G_COLOR[g]};padding:2px 6px;'
                    f'border-radius:3px;font-size:11px;font-weight:700;" title="{G_TIP[g]}">{g}</span>')

        def _fmt_mc(v):
            if v is None:
                return '<span style="color:#4b5563;">—</span>'
            if v >= 1_000_000:
                return f'<span style="color:#a78bfa;">${v/1_000_000:.2f}M</span>'
            if v >= 1_000:
                return f'<span style="color:#06b6d4;">${v/1_000:.1f}K</span>'
            return f'<span style="color:#9ca3af;">${v:.0f}</span>'

        if not tokens_data:
            html += '<tr><td colspan="7" style="text-align:center;padding:40px;color:#64748b;">No graduated tokens found</td></tr>'
        else:
            for i, t in enumerate(tokens_data, 1):
                mint_short = t['mint'] if t['mint'] else '—'
                creator_short = t['creator'] if t['creator'] else '—'
                html += f"""
                        <tr>
                            <td style="color:#6b7280;font-size:11px;">{i}</td>
                            <td style="font-weight:600;color:#e5e7eb;">{t['symbol']}</td>
                            <td><span class="address" title="{t['mint']}">{mint_short}</span></td>
                            <td><span class="address" title="{t['creator']}">{creator_short}</span></td>
                            <td style="text-align:center;">{_g_badge(t['peak_mc'])}</td>
                            <td style="text-align:right;">{_fmt_mc(t['peak_mc'])}</td>
                            <td style="text-align:right;">{_fmt_mc(t['current_mc'])}</td>
                        </tr>
                """

        html += """
                    </tbody>
                </table>
            </div>
        </body>
        </html>
        """

        return html

    except Exception as e:
        return f"<html><body style='background: var(--bg-dark); color: red;'><h1>Error</h1><p>{str(e)}</p></body></html>", 500


@app.route('/api/creator-analysis-queue-status')
def api_creator_analysis_queue_status():
    """Get status of creator analysis queue"""
    try:
        conn = db_connect(DB_PATH, timeout=5)
        conn.row_factory = sqlite3.Row
        cursor = conn.cursor()

        # Get queue status breakdown (exclude completed)
        cursor.execute("""
            SELECT
                status,
                COUNT(*) as count,
                ROUND(AVG(priority), 1) as avg_priority
            FROM creator_analysis_queue
            WHERE status != 'complete'
            GROUP BY status
        """)

        status_rows = cursor.fetchall()
        status_breakdown = {}
        for row in status_rows:
            status_breakdown[row['status']] = {
                'count': row['count'],
                'avg_priority': row['avg_priority']
            }

        # Get top priority items (exclude completed, show analyzing first, then pending)
        cursor.execute("""
            SELECT creator_address, priority, status,
                   json_extract(findings_cached, '$.risk_level') as risk_level,
                   last_analyzed_at
            FROM creator_analysis_queue
            WHERE status IN ('pending', 'analyzing', 'retry')
            ORDER BY CASE status
                WHEN 'analyzing' THEN 0
                WHEN 'pending' THEN 1
                WHEN 'retry' THEN 2
            END, priority DESC
            LIMIT 5
        """)

        top_items = []
        for row in cursor.fetchall():
            top_items.append({
                'creator_address': row['creator_address'],
                'priority': row['priority'],
                'status': row['status'],
                'risk_level': row['risk_level'],
                'last_analyzed_at': row['last_analyzed_at']
            })

        # Get active queue size (pending + analyzing + retry only)
        cursor.execute("""
            SELECT COUNT(*) as count FROM creator_analysis_queue
            WHERE status IN ('pending', 'analyzing', 'retry')
        """)
        total_queued = cursor.fetchone()['count'] or 0

        conn.close()

        return jsonify({
            'ok': True,
            'total_queued': total_queued,
            'status_breakdown': status_breakdown,
            'top_priority': top_items
        })
    except Exception as e:
        return jsonify({'error': str(e)}), 500



