@app.route('/api/creator-queue-status')
def api_creator_queue_status():
    """
    Get creator queue monitoring metrics.

    Returns:
    - total_in_queue: Total creators in work_queue
    - critical_count: Creators with priority >= 80
    - currently_processing: Creators currently locked
    - never_checked: Creators with attempts = 0
    - top_creators: Top 10 highest priority creators
    """
    try:
        conn = db_connect(DB_PATH, timeout=15)
        cur = conn.cursor()

        # Get queue overview stats
        now = int(__import__('time').time())

        cur.execute("SELECT COUNT(*) FROM work_queue")
        total_in_queue = cur.fetchone()[0]

        cur.execute("SELECT COUNT(*) FROM work_queue WHERE priority >= 80")
        critical_count = cur.fetchone()[0]

        cur.execute(f"SELECT COUNT(*) FROM work_queue WHERE locked_until > {now}")
        currently_processing = cur.fetchone()[0]

        cur.execute("SELECT COUNT(*) FROM work_queue WHERE attempts = 0")
        never_checked = cur.fetchone()[0]

        # Get top 20 priority creators
        cur.execute("""
            SELECT address, ROUND(priority, 1),
                   locked_until, next_run_at,
                   attempts, reason
            FROM work_queue
            ORDER BY priority DESC
            LIMIT 20
        """)

        top_creators = []
        for row in cur.fetchall():
            address = row[0]
            priority = row[1]
            locked_until = row[2]
            next_run_at = row[3]
            attempts = row[4]
            reason = row[5]

            # Determine status
            status = 'WAITING'
            if locked_until > now:
                status = 'PROCESSING'
            elif next_run_at <= now:
                status = 'READY'

            # Get activity stats for this creator
            cur.execute("""
                SELECT
                    COUNT(DISTINCT CASE WHEN source = ? THEN signature END) as outbound,
                    COUNT(DISTINCT CASE WHEN destination = ? THEN signature END) as inbound
                FROM sol_transfers
            """, (address, address))

            activity_row = cur.fetchone()
            outbound = activity_row[0] if activity_row[0] else 0
            inbound = activity_row[1] if activity_row[1] else 0
            total_activity = outbound + inbound

            # Look up label from multiple sources (priority order)
            label = None

            # 1. Check custom labels first
            cur.execute("SELECT label_name FROM address_labels WHERE address = ? LIMIT 1", (address,))
            row = cur.fetchone()
            if row:
                label = row[0]

            # 2. Check CEX wallets
            if not label:
                cur.execute("SELECT exchange_name FROM cex_wallets WHERE cex_address = ? LIMIT 1", (address,))
                row = cur.fetchone()
                if row:
                    label = f"{row[0]} (CEX)"

            # 3. Check INFRA funders
            if not label:
                cur.execute("SELECT funder_address FROM infra_funders_observed WHERE funder_address = ? LIMIT 1", (address,))
                if cur.fetchone():
                    label = "INFRA"

            top_creators.append({
                "address": address,
                "label": label,
                "display_name": label or address,
                "priority": priority,
                "status": status,
                "attempts": attempts,
                "reason": reason,
                "locked_until": locked_until,
                "next_run_at": next_run_at,
                "outbound_tx": outbound,
                "inbound_tx": inbound,
                "total_activity": total_activity
            })

        conn.close()

        return {
            "ok": True,
            "total_in_queue": total_in_queue,
            "critical_count": critical_count,
            "currently_processing": currently_processing,
            "never_checked": never_checked,
            "top_creators": top_creators
        }

    except Exception as e:
        try:
            conn.close()
        except:
            pass
        print(f"[QUEUE_STATUS] Error: {e}", flush=True)
        return {"ok": False, "error": str(e)}, 500


# =============================================================================
# SECOND-HOP NETWORK INTELLIGENCE — Phase 1 (SQL-only)
# =============================================================================

def _is_slow_2funder_bridge(row) -> bool:
    """
    Returns True for bridges that are weak enough to hide by default:
    - only 2 funders bridged
    - no burst timing detected (not in reason_codes)
    - span > 7 days (604800 seconds)
    These may be coincidental co-membership rather than coordination.
    """
    reason_codes = json.loads(row['reason_codes'] or '[]')
    has_burst = 'same_upstream_and_burst_timing' in reason_codes
    if has_burst:
        return False
    funders = row['funders_bridged_count'] if row['funders_bridged_count'] is not None else row['shared_funders']
    if funders > 2:
        return False
    span = row['time_span_seconds']
    return span is not None and span > 604800  # 7 days


@app.route('/api/second-hop-network-map')
def api_second_hop_network_map():
    """
    Return a map of network_name → max_second_hop_confidence for all networks.
    Used by the dashboard to render the 2H badge without per-row queries.
    Lightweight — SELECT two columns from networks_release.
    """
    try:
        conn = db_connect(DB_PATH, timeout=5)
        conn.row_factory = sqlite3.Row
        rows = conn.execute("""
            SELECT network_name, COALESCE(max_second_hop_confidence, 0) AS max_conf
            FROM networks_release
            WHERE max_second_hop_confidence >= 45
        """).fetchall()
        conn.close()
        result = {r['network_name']: r['max_conf'] for r in rows}
        return jsonify(result)
    except Exception as e:
        return jsonify({}), 200  # fail-open: badge just won't show


