@app.route('/api/second-hop/<creator_address>')
def api_second_hop_creator(creator_address: str):
    """
    Return second-hop upstream connections for a creator.

    Default: confidence >= 45, slow 2-funder bridges hidden.
    ?include_low_confidence=true: confidence >= 15, all bridges returned.
    """
    include_low = request.args.get('include_low_confidence', '').lower() == 'true'
    confidence_floor = 15 if include_low else 45
    try:
        conn = db_connect(DB_PATH, timeout=10)
        conn.row_factory = sqlite3.Row
        rows = conn.execute("""
            SELECT
                csh.upstream_address,
                csh.via_funder,
                csh.confidence_score,
                csh.risk_level,
                csh.reason_codes,
                csh.source,
                csh.built_at,
                fnm.network_name AS via_network,
                unb.time_span_seconds,
                unb.funders_bridged_count
            FROM creator_second_hop csh
            LEFT JOIN funder_network_map fnm ON fnm.funder_address = csh.via_funder
            LEFT JOIN upstream_network_bridge unb
                ON unb.upstream_address = csh.upstream_address
            WHERE csh.creator_address = ?
              AND csh.confidence_score >= ?
            GROUP BY csh.upstream_address, csh.via_funder
            ORDER BY csh.confidence_score DESC
        """, (creator_address, confidence_floor)).fetchall()
        display_map = get_network_display_names_map(conn)
        conn.close()

        result = []
        for r in rows:
            if not include_low and _is_slow_2funder_bridge(r):
                continue
            result.append({
                'upstream_address':   r['upstream_address'],
                'via_funder':         r['via_funder'],
                'via_network':        r['via_network'],
                'via_network_display_name': display_map.get(r['via_network'], {}).get('display_name') if r['via_network'] else None,
                'confidence_score':   r['confidence_score'],
                'risk_level':         r['risk_level'],
                'reason_codes':       json.loads(r['reason_codes'] or '[]'),
                'source':             r['source'],
                'built_at':           r['built_at'],
                'time_span_seconds':  r['time_span_seconds'],
                'suppressed':         False,
            })
        return jsonify({'creator_address': creator_address, 'second_hop': result})
    except Exception as e:
        return jsonify({'error': str(e)}), 500


@app.route('/api/network-coord/<network_name>')
def api_network_coord(network_name: str):
    """
    Return coordinated creator edges for all members of a network.
    Surfaces bridge funders, outside creator connections, and intra-network edges.
    """
    try:
        conn = db_connect(DB_PATH, timeout=5)
        conn.row_factory = sqlite3.Row
        conn.execute("PRAGMA query_only = ON")

        # Resolve display_name → network_name if needed
        resolved = conn.execute(
            "SELECT network_name FROM networks_release WHERE network_name = ? OR display_name = ? LIMIT 1",
            (network_name, network_name)
        ).fetchone()
        internal_name = resolved[0] if resolved else network_name

        members = [r[0] for r in conn.execute(
            "SELECT creator_address FROM network_membership WHERE network_name = ?",
            (internal_name,)
        ).fetchall()]

        if not members:
            conn.close()
            return jsonify({'edges': [], 'bridge_funders': [], 'outside_creators': [], 'intra_count': 0})

        member_set = set(members)
        placeholders = ','.join('?' * len(members))
        infra_wallet_rows = conn.execute(
            "SELECT address FROM infra_wallets"
        ).fetchall() if conn.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name='infra_wallets'"
        ).fetchone() else []
        infra_wallet_set = {row[0] for row in infra_wallet_rows}

        def classify_bridge_account(address: str) -> dict | None:
            if not address:
                return None
            try:
                from src.utils.infra_mapping import get_account_info, get_cex_info
            except Exception:
                get_account_info = None
                get_cex_info = None

            if get_account_info:
                infra_info = get_account_info(address)
                if infra_info:
                    return {
                        'type': 'INFRA',
                        'label': infra_info.get('name') or 'Infrastructure',
                        'category': infra_info.get('category') or 'infra',
                        'description': infra_info.get('description'),
                    }

            if get_cex_info:
                cex_info = get_cex_info(address)
                if cex_info:
                    return {
                        'type': 'CEX',
                        'label': cex_info.get('name') or cex_info.get('exchange') or 'CEX',
                        'category': cex_info.get('category') or 'cex',
                        'description': cex_info.get('description'),
                    }

            cex_row = conn.execute("""
                SELECT exchange_name, wallet_type
                FROM cex_wallets
                WHERE cex_address = ? AND is_active = 1
                LIMIT 1
            """, (address,)).fetchone()
            if cex_row:
                wallet_type = cex_row['wallet_type'] or 'wallet'
                exchange_name = cex_row['exchange_name'] or 'CEX'
                label = exchange_name if wallet_type in ('Hot Wallet', 'Exchange Wallet') else f"{exchange_name} {wallet_type}"
                return {
                    'type': 'CEX',
                    'label': label,
                    'category': wallet_type,
                    'description': None,
                }

            infra_row = conn.execute("""
                SELECT note
                FROM infra_funders_observed
                WHERE funder_address = ?
                LIMIT 1
            """, (address,)).fetchone()
            if infra_row:
                return {
                    'type': 'INFRA',
                    'label': infra_row['note'] or 'Observed Infrastructure',
                    'category': 'observed',
                    'description': infra_row['note'],
                }

            return None

        rows = conn.execute(f"""
            SELECT creator_a, creator_b, bridge_funder, confidence
            FROM coordinated_creator_edges
            WHERE creator_a IN ({placeholders}) OR creator_b IN ({placeholders})
            ORDER BY confidence DESC, bridge_funder
        """, members + members).fetchall()

        # Aggregate by bridge funder
        from collections import defaultdict
        import json as _json

        funder_data = defaultdict(lambda: {'edges': 0, 'intra': 0, 'outside': set(), 'members': set()})
        ignored_funder_data = defaultdict(lambda: {'edges': 0, 'intra': 0, 'outside': set(), 'members': set()})
        intra_count = 0
        outside_creators = {}

        for row in rows:
            a, b, funder, conf = row['creator_a'], row['creator_b'], row['bridge_funder'], row['confidence']
            a_in = a in member_set
            b_in = b in member_set
            is_ignored_funder = funder in infra_wallet_set
            fd = ignored_funder_data[funder] if is_ignored_funder else funder_data[funder]
            fd['edges'] += 1
            if a_in:
                fd['members'].add(a)
            if b_in:
                fd['members'].add(b)
            if a_in and b_in:
                fd['intra'] += 1
                if not is_ignored_funder:
                    intra_count += 1
            else:
                outside = b if a_in else a
                fd['outside'].add(outside)
                if not is_ignored_funder:
                    if outside not in outside_creators:
                        outside_creators[outside] = {'funders': [], 'count': 0}
                    outside_creators[outside]['count'] += 1
                    if funder not in outside_creators[outside]['funders']:
                        outside_creators[outside]['funders'].append(funder)

        # Build bridge_funders list sorted by total edges
        bridge_funders = []
        for funder, fd in sorted(funder_data.items(), key=lambda x: -x[1]['edges']):
            classification = classify_bridge_account(funder)
            bridge_funders.append({
                'funder': funder,
                'funder_label': classification['label'] if classification else None,
                'funder_type': classification['type'] if classification else None,
                'funder_category': classification['category'] if classification else None,
                'funder_description': classification['description'] if classification else None,
                'total_edges': fd['edges'],
                'intra_edges': fd['intra'],
                'outside_edges': fd['edges'] - fd['intra'],
                'outside_creators': len(fd['outside']),
                'member_count': len(fd['members']),
            })

        ignored_bridge_funders = []
        for funder, fd in sorted(ignored_funder_data.items(), key=lambda x: -x[1]['edges']):
            classification = classify_bridge_account(funder)
            ignored_bridge_funders.append({
                'funder': funder,
                'funder_label': classification['label'] if classification else None,
                'funder_type': classification['type'] if classification else 'INFRA',
                'funder_category': classification['category'] if classification else None,
                'funder_description': classification['description'] if classification else None,
                'total_edges': fd['edges'],
                'intra_edges': fd['intra'],
                'outside_edges': fd['edges'] - fd['intra'],
                'outside_creators': len(fd['outside']),
                'member_count': len(fd['members']),
                'ignored_for_coordination': True,
                'ignore_reason': 'Infrastructure/system-driven wallet; ignored for coordination analysis',
            })

        # Top outside creators
        top_outside = sorted(outside_creators.items(), key=lambda x: -x[1]['count'])[:20]

        conn.close()
        return jsonify({
            'network_name': network_name,
            'member_count': len(members),
            'total_edges': sum(f['total_edges'] for f in bridge_funders),
            'ignored_edge_count': sum(f['total_edges'] for f in ignored_bridge_funders),
            'intra_count': intra_count,
            'outside_creator_count': len(outside_creators),
            'bridge_funders': bridge_funders,
            'ignored_bridge_funders': ignored_bridge_funders,
            'top_outside_creators': [
                {'creator': c, 'edge_count': d['count'], 'via_funders': d['funders'][:3]}
                for c, d in top_outside
            ],
        })
    except Exception as exc:
        logger.exception('[api_network_coord] failed')
        return jsonify({'error': str(exc)}), 500


@app.route('/api/network-bridges/<network_name>')
def api_network_bridges(network_name: str):
    """
    Return networks connected to this network via shared upstream funders.

    Default: confidence >= 45, slow 2-funder bridges hidden.
    ?include_low_confidence=true: confidence >= 15, all bridges returned.
    """
    include_low = request.args.get('include_low_confidence', '').lower() == 'true'
    confidence_floor = 15 if include_low else 45
    try:
        conn = db_connect(DB_PATH, timeout=10)
        conn.row_factory = sqlite3.Row
        rows = conn.execute("""
            SELECT
                unb.upstream_address,
                CASE WHEN unb.network_a = ? THEN unb.network_b ELSE unb.network_a END AS connected_network,
                unb.shared_funders,
                unb.confidence_score,
                unb.risk_level,
                unb.reason_codes,
                unb.built_at,
                unb.time_span_seconds,
                unb.funders_bridged_count
            FROM upstream_network_bridge unb
            WHERE (unb.network_a = ? OR unb.network_b = ?)
              AND unb.confidence_score >= ?
              AND unb.is_excluded = 0
            ORDER BY unb.confidence_score DESC
        """, (network_name, network_name, network_name, confidence_floor)).fetchall()
        display_map = get_network_display_names_map(conn)
        conn.close()

        result = []
        for r in rows:
            if not include_low and _is_slow_2funder_bridge(r):
                continue
            result.append({
                'upstream_address':   r['upstream_address'],
                'connected_network':  r['connected_network'],
                'connected_network_display_name': display_map.get(r['connected_network'], {}).get('display_name'),
                'connected_network_display_reason': display_map.get(r['connected_network'], {}).get('reason'),
                'shared_funders':     r['shared_funders'],
                'confidence_score':   r['confidence_score'],
                'risk_level':         r['risk_level'],
                'reason_codes':       json.loads(r['reason_codes'] or '[]'),
                'built_at':           r['built_at'],
                'time_span_seconds':  r['time_span_seconds'],
                'source':             'transfer_index',
            })
        current_display = display_map.get(network_name, {})
        return jsonify({
            'network_name': network_name,
            'display_name': current_display.get('display_name') or network_name.replace('_', '-'),
            'display_name_reason': current_display.get('reason'),
            'bridges': result
        })
    except Exception as e:
        return jsonify({'error': str(e)}), 500


@app.route('/api/upstream-funder/<upstream_address>')
def api_upstream_funder(upstream_address: str):
    """
    Show all networks reachable from an upstream wallet and the funders it connects.
    """
    try:
        conn = db_connect(DB_PATH, timeout=10)
        conn.row_factory = sqlite3.Row

        # Networks this upstream bridges
        bridges = conn.execute("""
            SELECT network_a, network_b, shared_funders, confidence_score,
                   risk_level, reason_codes
            FROM upstream_network_bridge
            WHERE upstream_address = ?
              AND is_excluded = 0
            ORDER BY confidence_score DESC
        """, (upstream_address,)).fetchall()

        # Downstream funders
        funders = conn.execute("""
            SELECT funder_address, transfer_count, total_sol, avg_transfer_sol,
                   first_transfer_ts, last_transfer_ts, source, funders_touched,
                   last_seen_network_count
            FROM funder_upstream_links
            WHERE upstream_address = ?
              AND is_excluded = 0
        """, (upstream_address,)).fetchall()

        conn.close()

        return jsonify({
            'upstream_address': upstream_address,
            'bridges': [dict(r) for r in bridges],
            'downstream_funders': [{
                **dict(r),
                'reason_codes': None,  # not on funder link rows
            } for r in funders],
            'networks_bridged': len(set(
                n for r in bridges for n in (r['network_a'], r['network_b'])
            )),
        })
    except Exception as e:
        return jsonify({'error': str(e)}), 500


@app.route('/api/funding-queue')
def api_funding_queue():
    """List entries in the creator_funding_queue with stats and recent rows."""
    import time as _time
    conn = None
    try:
        conn = db_connect(DB_PATH, timeout=15)
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        now = int(_time.time())

        stats = cur.execute("""
            SELECT
                COUNT(*) AS total,
                SUM(CASE WHEN status = 'pending'  THEN 1 ELSE 0 END) AS pending,
                SUM(CASE WHEN status = 'running'  THEN 1 ELSE 0 END) AS running,
                SUM(CASE WHEN status = 'retry'    THEN 1 ELSE 0 END) AS retry,
                SUM(CASE WHEN status = 'complete' THEN 1 ELSE 0 END) AS complete,
                SUM(CASE WHEN status IN ('pending','retry') AND next_attempt_at <= ? THEN 1 ELSE 0 END) AS ready,
                COUNT(DISTINCT source) AS source_count
            FROM creator_funding_queue
        """, (now,)).fetchone()

        by_source = cur.execute("""
            SELECT
                COALESCE(source, 'unknown') AS source,
                COUNT(*) AS total,
                SUM(CASE WHEN status = 'complete' THEN 1 ELSE 0 END) AS complete,
                SUM(CASE WHEN status IN ('pending','retry','running') THEN 1 ELSE 0 END) AS active
            FROM creator_funding_queue
            GROUP BY source
            ORDER BY total DESC
        """).fetchall()

        rows = cur.execute("""
            SELECT
                cfq.creator_address,
                cfq.mint,
                cfq.status,
                COALESCE(cfq.source, 'unknown') AS source,
                cfq.attempts,
                cfq.last_error,
                cfq.next_attempt_at,
                cfq.created_at,
                cfq.updated_at,
                mc.symbol,
                mc.name AS token_name
            FROM creator_funding_queue cfq
            LEFT JOIN metadata_cache mc ON mc.mint = cfq.mint
            ORDER BY cfq.created_at DESC
            LIMIT 200
        """).fetchall()

        conn.close()

        return {
            "ok": True,
            "now": now,
            "stats": dict(stats) if stats else {},
            "by_source": [dict(r) for r in by_source],
            "rows": [dict(r) for r in rows],
        }
    except Exception as e:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
        return {"ok": False, "error": str(e)}, 500



@app.route('/api/funding-queue/coverage')
def api_funding_queue_coverage():
    """Creator funding coverage stats — % of migrated creators with funding data."""
    conn = None
    try:
        conn = db_connect(DB_PATH, timeout=10)
        conn.execute("PRAGMA query_only = ON")
        row = conn.execute("""
            SELECT
                COUNT(DISTINCT ta.earliest_tx_creator) AS total,
                COUNT(DISTINCT CASE WHEN EXISTS (
                    SELECT 1 FROM creator_funders cf WHERE cf.creator_address = ta.earliest_tx_creator
                ) THEN ta.earliest_tx_creator END) AS has_funding,
                COUNT(DISTINCT CASE WHEN NOT EXISTS (
                    SELECT 1 FROM creator_funders cf WHERE cf.creator_address = ta.earliest_tx_creator
                ) AND NOT EXISTS (
                    SELECT 1 FROM creator_funding_queue cfq WHERE cfq.creator_address = ta.earliest_tx_creator
                ) THEN ta.earliest_tx_creator END) AS missing_no_queue,
                COUNT(DISTINCT CASE WHEN NOT EXISTS (
                    SELECT 1 FROM creator_funders cf WHERE cf.creator_address = ta.earliest_tx_creator
                ) AND EXISTS (
                    SELECT 1 FROM creator_funding_queue cfq WHERE cfq.creator_address = ta.earliest_tx_creator
                ) THEN ta.earliest_tx_creator END) AS missing_queued,
                COUNT(DISTINCT CASE WHEN ta.created_at >= strftime('%s','now') - 86400
                    AND NOT EXISTS (
                        SELECT 1 FROM creator_funders cf WHERE cf.creator_address = ta.earliest_tx_creator
                    ) THEN ta.earliest_tx_creator END) AS missing_24h
            FROM token_analysis ta
            WHERE ta.earliest_tx_creator IS NOT NULL AND ta.migrated_at IS NOT NULL
        """).fetchone()
        conn.close()
        total = row[0] or 1
        has_funding = row[1] or 0
        missing_no_queue = row[2] or 0
        missing_queued = row[3] or 0
        missing_24h = row[4] or 0
        return {
            "ok": True,
            "total_creators": total,
            "has_funding": has_funding,
            "missing_no_queue": missing_no_queue,
            "missing_queued": missing_queued,
            "missing_24h": missing_24h,
            "coverage_pct": round(has_funding / total * 100, 1),
            "missing_pct": round((missing_no_queue + missing_queued) / total * 100, 1),
        }
    except Exception as e:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
        return {"ok": False, "error": str(e)}, 500


@app.route('/api/funding-queue/clear', methods=['POST'])
def api_funding_queue_clear():
    """Delete all rows from creator_funding_queue."""
    try:
        conn = db_connect(DB_PATH, timeout=10)
        conn.execute("PRAGMA journal_mode=WAL")
        cursor = conn.cursor()
        cursor.execute("DELETE FROM creator_funding_queue")
        deleted = cursor.rowcount
        conn.commit()
        conn.close()
        return jsonify({"ok": True, "deleted": deleted})
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 500


