@app.route('/api/webhook/funder', methods=['POST'])
def webhook_funder_event():
    """
    Receive funder webhook events from Helius.
    Dedupes by (signature, funder_address) and stores in database.
    """
    try:
        payload = request.get_json()

        if not payload:
            return jsonify({"error": "empty payload"}), 400

        signature = payload.get("signature")
        slot = payload.get("slot")
        block_time = payload.get("blockTime")
        source = payload.get("source")
        destination = payload.get("destination")
        mint = payload.get("mint")

        if not signature or not source or not destination:
            return jsonify({"error": "missing required fields"}), 400

        direction = None
        counterparty = None
        amount_sol = 0

        conn = db_connect(DB_PATH, timeout=15)
        cursor = conn.cursor()

        # Check if source is a watched funder (transfer OUT)
        cursor.execute("""
            SELECT 1 FROM funder_watchlist
            WHERE funder_address = ? AND is_active = 1
        """, (source,))

        if cursor.fetchone():
            direction = "OUT"
            counterparty = destination
            native_transfers = payload.get("nativeTransfers", [])
            if native_transfers:
                amount_sol = sum(t.get("amount", 0) for t in native_transfers) / 1e9

        # Check if destination is a watched funder (transfer IN)
        cursor.execute("""
            SELECT 1 FROM funder_watchlist
            WHERE funder_address = ? AND is_active = 1
        """, (destination,))

        if cursor.fetchone():
            direction = "IN"
            counterparty = source
            native_transfers = payload.get("nativeTransfers", [])
            if native_transfers:
                amount_sol = sum(t.get("amount", 0) for t in native_transfers) / 1e9

        if not direction:
            conn.close()
            return jsonify({"status": "ok"}), 200

        # Insert event (dedupe by UNIQUE constraint)
        funder = source if direction == "OUT" else destination
        try:
            cursor.execute("""
                INSERT INTO funder_webhook_events
                (funder_address, signature, slot, block_time, direction, counterparty, amount_sol, mint, raw_payload)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            """, (funder, signature, slot, block_time, direction, counterparty, amount_sol, mint, json.dumps(payload)))
            conn.commit()
            print(f"[WEBHOOK_FUNDER] ✅ {direction}: {funder[:8]}... <-> {counterparty[:8]}... ({amount_sol:.4f} SOL)", flush=True)
        except sqlite3.IntegrityError:
            pass  # Duplicate event
        finally:
            conn.close()

        return jsonify({"status": "ok"}), 200

    except Exception as e:
        print(f"[WEBHOOK_FUNDER] ⚠ Error: {e}", flush=True)
        import traceback
        traceback.print_exc()
        return jsonify({"error": str(e)}), 500


@app.route('/api/funder-watchlist/summary')
def funder_watchlist_summary():
    """Get summary of funder watchlist by risk tier."""
    try:
        conn = db_connect(DB_PATH, timeout=15)
        cursor = conn.cursor()

        summary = {}
        for tier in ["CRITICAL", "HIGH", "MEDIUM", "LOW"]:
            cursor.execute("""
                SELECT COUNT(*) as count, COALESCE(SUM(risk_score), 0) as total_risk
                FROM funder_watchlist
                WHERE webhook_group_id = ? AND is_active = 1
            """, (tier,))
            row = cursor.fetchone()
            summary[tier] = {
                "count": row[0] if row else 0,
                "total_risk_score": row[1] if row else 0,
            }

        conn.close()
        return jsonify(summary)

    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route('/api/funder-watchlist/top-risky')
def funder_watchlist_top_risky():
    """Get top 20 most risky funders."""
    try:
        conn = db_connect(DB_PATH, timeout=15)
        cursor = conn.cursor()

        cursor.execute("""
            SELECT funder_address, risk_score, webhook_group_id, risk_reasons
            FROM funder_watchlist
            WHERE is_active = 1
            ORDER BY risk_score DESC
            LIMIT 20
        """)

        rows = cursor.fetchall()
        result = []
        for row in rows:
            risk_reasons = json.loads(row[3]) if row[3] else []
            result.append({
                "funder_address": row[0],
                "risk_score": row[1],
                "risk_tier": row[2],
                "risk_reasons": risk_reasons,
            })

        conn.close()
        return jsonify(result)

    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route('/api/webhook/creator-movement', methods=['POST'])
def webhook_creator_movement():
    """
    POST /api/webhook/creator-movement
    Receives Helius enhanced_transactions webhook for creator wallet SOL movements.
    Payload: list of enhanced transaction objects.
    Returns 200 immediately; processing is fire-and-forget via asyncio.
    """
    import asyncio as _asyncio
    try:
        payload = request.get_json(silent=True)
        if not payload:
            return "ok", 200
        if isinstance(payload, dict):
            payload = [payload]
        if not isinstance(payload, list):
            return "ok", 200

        from src.creators.movement import parse_creator_sol_movement
        from src.creators.service import handle_creator_stream_event
        from src.creators.repository import CreatorRepository

        creator_db_path = os.path.join(
            os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))),
            "pumpswap_tokens.db",
        )

        async def _process():
            import asyncio
            lock = asyncio.Lock()
            repo = CreatorRepository(db_path=creator_db_path, db_lock=lock)
            await repo.ensure_schema()
            # First collect all known creator addresses to avoid per-tx DB reads
            known: set[str] = set()
            async with lock:
                import sqlite3 as _sq
                conn = _sq.connect(creator_db_path, timeout=10)
                conn.row_factory = _sq.Row
                rows = conn.execute(
                    "SELECT creator_address FROM creator_profile WHERE history_status != 'unknown'"
                ).fetchall()
                conn.close()
            known = {r["creator_address"] for r in rows}

            for tx in payload:
                if not isinstance(tx, dict):
                    continue
                sig = tx.get("signature")
                if not sig:
                    continue
                # Only process if one of the accounts is a known creator
                from src.creators.movement import _account_keys
                accounts = set(_account_keys(tx))
                relevant = accounts & known
                for creator in relevant:
                    event = parse_creator_sol_movement(tx, creator, source="webhook")
                    if event is None:
                        continue
                    await handle_creator_stream_event(
                        {
                            "creator_address": event.creator_address,
                            "signature":       event.signature,
                            "slot":            event.slot,
                            "block_time":      event.block_time,
                            "net_lamports":    event.net_lamports,
                            "abs_lamports":    event.abs_lamports,
                            "direction":       event.direction,
                            "counterparty":    event.counterparty,
                            "source":          event.source,
                        },
                        repo=repo,
                    )

        try:
            loop = _asyncio.get_event_loop()
            if loop.is_running():
                _asyncio.ensure_future(_process())
            else:
                loop.run_until_complete(_process())
        except Exception as e:
            print(f"[CREATOR_WEBHOOK] Processing error: {e}", flush=True)

        return "ok", 200
    except Exception as e:
        print(f"[CREATOR_WEBHOOK] Handler error: {e}", flush=True)
        return "ok", 200


@app.route('/api/webhook/pumpfun-birth', methods=['POST'])
def webhook_pumpfun_birth():
    """
    POST /api/webhook/pumpfun-birth
    Receives Helius enhanced_transactions webhook for pump.fun CREATE events.
    Writes each signature to webhook_birth_queue; the listener process drains it
    on a 5-second poll and calls handle_birth() for each new entry.
    Returns 200 immediately.
    """
    import sqlite3 as _sq
    try:
        payload = request.get_json(silent=True)
        if not payload:
            return "ok", 200
        if isinstance(payload, dict):
            payload = [payload]
        if not isinstance(payload, list):
            return "ok", 200

        db_path = _DEFAULT_DB_PATH
        # Ensure table exists (idempotent)
        conn = _sq.connect(db_path, timeout=10)
        with conn:
            conn.execute("""
                CREATE TABLE IF NOT EXISTS webhook_birth_queue (
                    id        INTEGER PRIMARY KEY AUTOINCREMENT,
                    signature TEXT    NOT NULL UNIQUE,
                    consumed  INTEGER NOT NULL DEFAULT 0,
                    created_at INTEGER NOT NULL DEFAULT (strftime('%s','now'))
                )
            """)

        inserted = skipped = 0
        for tx in payload:
            if not isinstance(tx, dict):
                continue
            sig = tx.get("signature")
            if not sig:
                continue
            # Pre-filter: only queue if logs look like a CREATE, not a buy/sell/migrate.
            # Saves an RPC getTransaction call for every non-birth pump.fun tx.
            logs_text = " ".join(tx.get("logs") or []).lower()
            is_create = (
                "instruction: create" in logs_text
                or "initializemint" in logs_text
            )
            is_noise = (
                "instruction: buy" in logs_text
                or "instruction: sell" in logs_text
                or "instruction: migrate" in logs_text
                or "migratebondingcurvecreator" in logs_text
            )
            if not is_create or is_noise:
                skipped += 1
                continue
            try:
                with conn:
                    conn.execute(
                        "INSERT OR IGNORE INTO webhook_birth_queue (signature) VALUES (?)", (sig,)
                    )
                    inserted += 1
            except Exception:
                pass
        conn.close()
        print(f"[BIRTH_WEBHOOK] Queued {inserted} birth signatures (skipped {skipped} non-create)", flush=True)
        try:
            from src.metrics.usage_tracker import record_webhook
            wh_id = os.getenv("PUMPFUN_BIRTH_WEBHOOK_ID", "pumpfun-birth")
            if inserted:
                record_webhook(wh_id, "main", "birth", count=inserted)
            if skipped:
                record_webhook(wh_id, "main", "filtered_out", count=skipped)
        except Exception:
            pass
    except Exception as e:
        print(f"[BIRTH_WEBHOOK] Handler error: {e}", flush=True)
        try:
            from src.metrics.usage_tracker import record_webhook
            wh_id = os.getenv("PUMPFUN_BIRTH_WEBHOOK_ID", "pumpfun-birth")
            record_webhook(wh_id, "main", "error", count=1, note=str(e))
        except Exception:
            pass
    return "ok", 200


