@app.route('/api/watchtower/operator-clusters')
def api_watchtower_operator_clusters():
    """WATCH-style operator clusters. Only returns clusters with WATCH token members."""
    conn = db_connect(DB_PATH, timeout=5)
    conn.row_factory = sqlite3.Row
    limit = int(request.args.get('limit', 50))

    clusters = []
    try:
        for row in conn.execute("""
            SELECT * FROM wt_operator_clusters
            WHERE watch_token_count > 0 OR origin = 'seed'
            ORDER BY watch_token_count DESC, confidence DESC, last_seen DESC
            LIMIT ?
        """, (limit,)).fetchall():
            c = dict(row)
            fp = conn.execute(
                "SELECT * FROM wt_operator_fingerprints WHERE cluster_id=? ORDER BY updated_at DESC LIMIT 1",
                (c['cluster_id'],)
            ).fetchone()
            c['fingerprint'] = dict(fp) if fp else None
            c['member_count'] = conn.execute(
                "SELECT COUNT(*) FROM wt_cluster_members WHERE cluster_id=?",
                (c['cluster_id'],)
            ).fetchone()[0]
            # Funding origin distribution for this cluster
            c['funding_origins'] = _compute_cluster_funding_origins(c['cluster_id'], conn)
            clusters.append(c)
    except Exception as e:
        conn.close()
        return jsonify({"error": str(e)}), 500

    total_eligible = 0
    possible = 0
    try:
        total_eligible = conn.execute("SELECT COUNT(*) FROM watch_candidate_tokens").fetchone()[0]
        possible = conn.execute(
            "SELECT COUNT(*) FROM watch_candidate_tokens WHERE classified_as='WATCH_LIKE_NEW_OP'"
        ).fetchone()[0]
    except Exception:
        pass

    conn.close()
    return jsonify({
        "clusters":        clusters,
        "count":           len(clusters),
        "total_eligible":  total_eligible,
        "possible_swarms": possible,
    })


@app.route('/api/watchtower/operator-candidates')
def api_watchtower_operator_candidates():
    """WATCH-style token candidates classified by the WATCH pipeline."""
    conn = db_connect(DB_PATH, timeout=5)
    conn.row_factory = sqlite3.Row
    limit    = int(request.args.get('limit', 200))
    min_conf = float(request.args.get('min_conf', 0.0))

    candidates = []
    yield_stats = {}
    watch_total = 0
    recent_live_count = 0
    try:
        rows = conn.execute("""
            SELECT wct.mint as token_mint, wct.creator_address, wct.prediction_score,
                   wct.has_sol_flows, wct.classified_as, wct.classification_conf,
                   wct.classification_reason, wct.cluster_id, wct.added_at as scanned_at,
                   wct.classified_as as operator_class,
                   wct.classification_conf as confidence,
                   wct.creator_address as provisioner_wallet
            FROM watch_candidate_tokens wct
            WHERE wct.classification_conf >= ?
            ORDER BY
                CASE wct.classified_as WHEN 'WATCHTOWER' THEN 0 WHEN 'WATCH_LIKE_NEW_OP' THEN 1 ELSE 2 END,
                wct.classification_conf DESC
            LIMIT ?
        """, (min_conf, limit)).fetchall()
        candidates = []
        for r in rows:
            c = dict(r)
            origin, reason = _funding_origin_for_creator(c['creator_address'], conn)
            c['funding_origin'] = origin
            c['funding_reason'] = reason
            c['is_alpha_family'] = _is_alpha_family_creator(c['creator_address'], conn)
            candidates.append(c)

        # ── Recent LIVE WATCH launches (not yet swarm-classified) ──────────
        # watch_candidate_tokens only holds post-migration *classified* tokens and
        # lags behind live launches. token_prediction_scores(risk_level='WATCH') is
        # the live launch feed — surface the most recent ones here tagged
        # UNCLASSIFIED so analysts have visibility on fresh launches before the
        # classifier reaches them. Skip any mint already in the classified set above.
        classified_mints = {c.get('token_mint') for c in candidates}
        recent_limit = int(request.args.get('recent_limit', 50))
        recent_cutoff = int(time.time()) - int(request.args.get('recent_window_s', 86400))
        recent_rows = conn.execute("""
            SELECT tps.mint, tps.creator_address, tps.prediction_score,
                   tps.creator_was_fresh, tps.predicted_at, mc.name AS token_name
            FROM token_prediction_scores tps
            LEFT JOIN metadata_cache mc ON mc.mint = tps.mint
            WHERE tps.risk_level = 'WATCH' AND tps.predicted_at > ?
            ORDER BY tps.predicted_at DESC
            LIMIT ?
        """, (recent_cutoff, recent_limit * 2)).fetchall()
        recent = []
        for r in recent_rows:
            if r['mint'] in classified_mints:
                continue
            cr = r['creator_address']
            origin, reason = _funding_origin_for_creator(cr, conn) if cr else (None, None)
            recent.append({
                'token_mint':           r['mint'],
                'mint':                 r['mint'],
                'token_name':           r['token_name'],
                'creator_address':      cr,
                'provisioner_wallet':   cr,
                'prediction_score':     r['prediction_score'],
                'classified_as':        'UNCLASSIFIED',
                'operator_class':       'UNCLASSIFIED',
                'classification_conf':  None,
                'confidence':           None,
                'classification_reason':'New WATCH launch — not yet classified',
                'cluster_id':           None,
                'has_sol_flows':        None,
                'scanned_at':           r['predicted_at'],
                'creator_was_fresh':    r['creator_was_fresh'],
                'funding_origin':       origin,
                'funding_reason':       reason,
                'is_alpha_family':      _is_alpha_family_creator(cr, conn) if cr else False,
                'is_recent_live':       True,
            })
            if len(recent) >= recent_limit:
                break
        # Recent live launches lead the table (newest-first); classified below.
        candidates = recent + candidates
        recent_live_count = len(recent)

        total_eligible     = conn.execute("SELECT COUNT(*) FROM watch_candidate_tokens").fetchone()[0]
        classified_wt      = conn.execute("SELECT COUNT(*) FROM watch_candidate_tokens WHERE classified_as='WATCHTOWER'").fetchone()[0]
        classified_new_op  = conn.execute("SELECT COUNT(*) FROM watch_candidate_tokens WHERE classified_as='WATCH_LIKE_NEW_OP'").fetchone()[0]
        classified_unknown = conn.execute("SELECT COUNT(*) FROM watch_candidate_tokens WHERE classified_as='UNKNOWN'").fetchone()[0]
        with_sol_flows     = conn.execute("SELECT COUNT(*) FROM watch_candidate_tokens WHERE has_sol_flows=1").fetchone()[0]
        confirmed          = conn.execute("SELECT COUNT(*) FROM wt_operator_clusters WHERE origin='watch_pipeline'").fetchone()[0]
        service_excl       = conn.execute("""
            SELECT COUNT(*) FROM token_prediction_scores tps
            WHERE tps.risk_level='WATCH' AND tps.creator_was_fresh=1
              AND EXISTS (SELECT 1 FROM infra_wallets iw WHERE iw.address=tps.creator_address
                          AND iw.type NOT IN ('bonding_curve','pumpswap_pool','pool'))
        """).fetchone()[0]
        watch_total = conn.execute(
            "SELECT COUNT(*) FROM token_prediction_scores WHERE risk_level='WATCH'"
        ).fetchone()[0]

        yield_stats = {
            "total_eligible":       total_eligible,
            "classified_watchtower": classified_wt,
            "classified_new_op":    classified_new_op,
            "classified_unknown":   classified_unknown,
            "with_sol_flows":       with_sol_flows,
            "service_excluded":     service_excl,
            "confirmed":            confirmed,
            # legacy keys kept for template compatibility
            "total":       total_eligible,
            "scanning":    0,
            "possible":    classified_new_op,
            "no_sigs":     0,
            "insuff_data": 0,
            "low_buyers":  0,
            "wide_window": 0,
            "already_attr": classified_wt,
        }
    except Exception as e:
        conn.close()
        return jsonify({"error": str(e)}), 500

    conn.close()
    return jsonify({"candidates": candidates, "count": len(candidates),
                    "recent_live_count": recent_live_count,
                    "yield": yield_stats, "watch_total": watch_total})


@app.route('/api/watchtower/graph')
def api_watchtower_graph():
    """
    Fast topology graph synthesized from existing tables.
    Returns {nodes, links} in D3 format.
    Prefers wt_graph_nodes/edges if populated; synthesizes from fee_payers +
    staged_wallets + creator_funders otherwise.
    """
    conn = db_connect(DB_PATH, timeout=5)
    conn.row_factory = sqlite3.Row
    limit_nodes = int(request.args.get('limit', 300))

    nodes = []
    links = []
    node_ids = set()

    try:
        # ── Try native graph tables first ──────────────────────────
        native_nodes = conn.execute(
            "SELECT address, node_type, campaign_id, state, score FROM wt_graph_nodes LIMIT ?",
            (limit_nodes,)
        ).fetchall()

        if native_nodes:
            for r in native_nodes:
                nodes.append({
                    "id": r["address"], "node_type": r["node_type"],
                    "campaign_id": r["campaign_id"], "state": r["state"],
                    "score": r["score"],
                })
                node_ids.add(r["address"])
            for r in conn.execute(
                "SELECT from_address, to_address, edge_type, amount_sol, campaign_id FROM wt_graph_edges LIMIT ?",
                (limit_nodes * 3,)
            ).fetchall():
                if r["from_address"] in node_ids and r["to_address"] in node_ids:
                    links.append({
                        "source": r["from_address"], "target": r["to_address"],
                        "edge_type": r["edge_type"], "amount_sol": r["amount_sol"],
                        "campaign_id": r["campaign_id"],
                    })
        else:
            # ── Synthesize from existing data ───────────────────────
            # Known infra anchors
            TREASURY  = "44orWS68MqXG198M3YXyZoNrYtsNhgnNhtUT5SavqJFM"
            SIGNALLER = "44orA1BxQfFaX2iMjRbWstoqqWBE7ag8BD93ikxR4JFM"

            def add_node(nid, ntype, **kw):
                if nid and nid not in node_ids:
                    nodes.append({"id": nid, "node_type": ntype, **kw})
                    node_ids.add(nid)

            def add_link(src, tgt, etype, **kw):
                if src in node_ids and tgt in node_ids:
                    links.append({"source": src, "target": tgt, "edge_type": etype, **kw})

            # Treasury + Signaller
            add_node(TREASURY,  "TREASURY",  campaign_id=None)
            add_node(SIGNALLER, "RELAY",     campaign_id=None)

            # Sub-provisioners from staged wallets
            prov_rows = conn.execute("""
                SELECT provisioner_address,
                       COUNT(*) AS wallet_count,
                       SUM(CASE WHEN first_move_type='pAMM_trader' THEN 1 ELSE 0 END) AS trader_count,
                       MAX(provisioned_at) AS last_at
                FROM wt_staged_wallets
                GROUP BY provisioner_address
                ORDER BY last_at DESC
                LIMIT 20
            """).fetchall()

            for r in prov_rows:
                prov = r["provisioner_address"]
                add_node(prov, "SUB_PROV", campaign_id=prov[:8],
                         wallet_count=r["wallet_count"], trader_count=r["trader_count"])
                add_link(TREASURY, prov, "treasury_to_subprov")

                # Add a representative TRADER_SWARM node per provisioner
                swarm_id = f"swarm_{prov[:8]}"
                if r["trader_count"] and r["trader_count"] > 0:
                    add_node(swarm_id, "TRADER_SWARM", campaign_id=prov[:8],
                             wallet_count=r["trader_count"])
                    add_link(prov, swarm_id, "subprov_to_wallet")

            # Fee payers as additional operators (sample)
            fee_rows = conn.execute("""
                SELECT address, total_sol_sent, last_seen_at
                FROM watchtower_fee_payers
                ORDER BY last_seen_at DESC
                LIMIT 40
            """).fetchall()
            for r in fee_rows:
                add_node(r["address"], "SUB_PROV",
                         campaign_id=None, total_sol=r["total_sol_sent"])
                add_link(TREASURY, r["address"], "treasury_to_subprov",
                         amount_sol=r["total_sol_sent"])

            # Creator wallets from fingerprint funding
            cr_rows = conn.execute("""
                SELECT cf.creator_address, cf.funder_address, cf.amount_sol,
                       cs.score
                FROM creator_funders cf
                LEFT JOIN wt_candidate_scores cs ON cs.wallet_address = cf.creator_address
                WHERE cf.amount_sol LIKE '%.10203928'
                ORDER BY cf.amount_sol DESC
                LIMIT 80
            """).fetchall()
            for r in cr_rows:
                score = r["score"] or 0
                ntype = "CREATOR_HC" if score >= 85 else "CREATOR"
                add_node(r["creator_address"], ntype,
                         score=score, campaign_id=r["funder_address"][:8] if r["funder_address"] else None)
                funder = r["funder_address"]
                # Link from funder if known, else from treasury
                src = funder if funder in node_ids else TREASURY
                add_link(src, r["creator_address"], "creator_link",
                         amount_sol=r["amount_sol"])

            # Candidate scores not yet in creator_funders
            cand_rows = conn.execute("""
                SELECT wallet_address, score FROM wt_candidate_scores
                WHERE score >= 60
                ORDER BY score DESC LIMIT 30
            """).fetchall() if _table_exists_cached('wt_candidate_scores') else []
            for r in cand_rows:
                ntype = "CREATOR_HC" if r["score"] >= 85 else "CREATOR"
                add_node(r["wallet_address"], ntype, score=r["score"])

    except Exception as e:
        conn.close()
        return jsonify({"error": str(e), "nodes": [], "links": []}), 500

    conn.close()
    return jsonify({"nodes": nodes, "links": links,
                    "synthesized": len(nodes) > 0,
                    "node_count": len(nodes), "link_count": len(links)})


@app.route('/api/watchtower/backfill-infra', methods=['POST'])
def api_watchtower_backfill_infra():
    """
    Backfill SIGNALLER + TREASURY + TREASURY-UP transactions via RPC.
    Discovers any wallets funded by TREASURY during the gap and adds them as launch candidates.
    """
    def _run():
        try:
            import requests as _req
            rpc_url = os.getenv("HELIUS_RPC_URL", "")
            if not rpc_url:
                print("[WT_BACKFILL] No RPC URL", flush=True)
                return

            bconn = db_connect(DB_PATH, timeout=30)
            bconn.row_factory = sqlite3.Row

            total_new = 0
            for infra_addr, role in _WT_INFRA_ROLES.items():
                print(f"[WT_BACKFILL] Scanning {role} ({infra_addr[:20]}…)", flush=True)

                # Paginate signatures — go back up to 2000 txs (covers ~2 days for low-volume infra)
                all_sigs = []
                before = None
                for _ in range(4):  # 4 pages × 500 = 2000 sigs max
                    params = {"limit": 500}
                    if before:
                        params["before"] = before
                    resp = _req.post(rpc_url, json={
                        "jsonrpc": "2.0", "id": 1,
                        "method": "getSignaturesForAddress",
                        "params": [infra_addr, params]
                    }, timeout=30)
                    page = resp.json().get("result") or []
                    if not page:
                        break
                    all_sigs.extend(page)
                    if len(page) < 500:
                        break
                    before = page[-1].get("signature")

                print(f"[WT_BACKFILL] {role}: {len(all_sigs)} signatures to process", flush=True)

                for s in all_sigs:
                    sig = s.get("signature")
                    if not sig:
                        continue
                    # Skip already-recorded
                    if bconn.execute(
                        "SELECT 1 FROM watchtower_infra_events WHERE signature=? AND infra_address=?",
                        (sig, infra_addr)
                    ).fetchone():
                        continue

                    tx_resp = _req.post(rpc_url, json={
                        "jsonrpc": "2.0", "id": 1,
                        "method": "getTransaction",
                        "params": [sig, {"encoding": "jsonParsed", "maxSupportedTransactionVersion": 0}]
                    }, timeout=15)
                    tx_data = tx_resp.json().get("result")
                    if not tx_data:
                        continue

                    block_time = tx_data.get("blockTime") or int(time.time())
                    meta = tx_data.get("meta") or {}
                    pre  = meta.get("preBalances") or []
                    post = meta.get("postBalances") or []
                    accs_raw = (tx_data.get("transaction") or {}).get("message", {}).get("accountKeys") or []
                    accs = [a.get("pubkey", "") if isinstance(a, dict) else a for a in accs_raw]

                    if infra_addr not in accs:
                        continue
                    infra_idx = accs.index(infra_addr)

                    for i, acc in enumerate(accs):
                        if acc == infra_addr or not acc or i >= len(pre) or i >= len(post):
                            continue
                        delta_lamports = post[i] - pre[i]
                        if delta_lamports == 0:
                            continue
                        amount_sol = abs(delta_lamports) / 1e9

                        # Determine direction relative to infra_addr
                        infra_delta = (post[infra_idx] - pre[infra_idx]) if infra_idx < len(pre) else 0
                        if infra_delta < 0 and delta_lamports > 0:
                            # infra lost SOL, this account gained = outbound from infra
                            direction = "outbound"
                            counterparty = acc
                        elif infra_delta > 0 and delta_lamports < 0:
                            # infra gained SOL, this account lost = inbound to infra
                            direction = "inbound"
                            counterparty = acc
                        else:
                            continue

                        bconn.execute(
                            """INSERT OR IGNORE INTO watchtower_infra_events
                               (signature, block_time, infra_address, infra_role, direction, counterparty, amount_sol)
                               VALUES (?, ?, ?, ?, ?, ?, ?)""",
                            (sig, block_time, infra_addr, role, direction, counterparty, amount_sol),
                        )

                        # TREASURY outbound → potential new creator
                        if role == "TREASURY" and direction == "outbound":
                            already = bconn.execute(
                                "SELECT 1 FROM creator_risk_scores WHERE creator_address=? AND watchtower_related=1",
                                (counterparty,)
                            ).fetchone()
                            if not already:
                                bconn.execute(
                                    """INSERT INTO watchtower_launch_candidates
                                       (address, source_operator, candidate_reason, confidence,
                                        first_signal_at, last_signal_at, evidence_json)
                                       VALUES (?, ?, 'treasury_funded', 'high', ?, ?,
                                               json_object('treasury_tx', ?, 'amount_sol', ?, 'block_time', ?))
                                       ON CONFLICT(address) DO UPDATE SET
                                           last_signal_at = MAX(last_signal_at, excluded.last_signal_at),
                                           evidence_json  = excluded.evidence_json""",
                                    (counterparty, _WT_TREASURY_ADDR, block_time, block_time,
                                     sig, amount_sol, block_time),
                                )
                                total_new += 1
                                print(
                                    f"[WT_BACKFILL] 🟡 New TREASURY recipient: {counterparty[:20]}… "
                                    f"{amount_sol:.4f} SOL",
                                    flush=True,
                                )

                bconn.commit()

            bconn.close()
            print(f"[WT_BACKFILL] Done — {total_new} new treasury recipients discovered", flush=True)
        except Exception as exc:
            import traceback
            print(f"[WT_BACKFILL] Error: {exc}", flush=True)
            traceback.print_exc()

    import threading as _thr
    _thr.Thread(target=_run, daemon=True, name="wt-infra-backfill").start()
    return jsonify({"status": "backfill started — check server logs for progress"})


# ---------------------------------------------------------------------------
# Creator pipeline status — profile + watch state + SOL movement ledger
# ---------------------------------------------------------------------------

def _creator_db_path():
    return os.path.join(
        os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))),
        "pumpswap_tokens.db",
    )


@app.route('/api/creator-pipeline-status/<creator_address>')
def api_creator_pipeline_status(creator_address: str):
    """
    Returns creator_profile + creator_activity_state + last 30 SOL movements
    from the creator pipeline DB (pumpswap_tokens.db).
    """
    try:
        import sqlite3 as _sq
        cdb = _creator_db_path()
        conn = _sq.connect(cdb, timeout=10)
        conn.row_factory = _sq.Row

        profile = conn.execute(
            "SELECT * FROM creator_profile WHERE creator_address = ?",
            (creator_address,)
        ).fetchone()

        state = conn.execute(
            "SELECT * FROM creator_activity_state WHERE creator_address = ?",
            (creator_address,)
        ).fetchone()

        movements = conn.execute(
            """
            SELECT slot, block_time, net_lamports, abs_lamports,
                   direction, counterparty, source, signature
            FROM creator_sol_movements
            WHERE creator_address = ?
            ORDER BY slot DESC
            LIMIT 30
            """,
            (creator_address,)
        ).fetchall()

        # 24h flow totals
        cutoff = int(__import__('time').time()) - 86400
        flow = conn.execute(
            """
            SELECT
                SUM(CASE WHEN direction='in'  THEN abs_lamports ELSE 0 END) as total_in,
                SUM(CASE WHEN direction='out' THEN abs_lamports ELSE 0 END) as total_out,
                COUNT(*) as total_events
            FROM creator_sol_movements
            WHERE creator_address = ? AND block_time >= ?
            """,
            (creator_address, cutoff)
        ).fetchone()

        conn.close()

        def _row(r):
            return dict(r) if r else {}

        p = _row(profile)
        s = _row(state)
        f = _row(flow)

        return jsonify({
            "creator_address": creator_address,
            "profile": {
                "history_status":        p.get("history_status", "unknown"),
                "coverage_mode":         p.get("coverage_mode", "forward_only"),
                "token_count_seen":      p.get("token_count_seen", 0),
                "last_launch_at":        p.get("last_launch_at"),
                "last_activity_at":      p.get("last_activity_at"),
                "baselined_at":          p.get("baselined_at"),
                "first_seen_at":         p.get("first_seen_at"),
            } if p else None,
            "watch": {
                "status":           s.get("watch_status"),
                "webhook_id":       s.get("watch_webhook_id"),
                "registered_at":    s.get("watch_registered_at"),
                "last_checked_at":  s.get("watch_last_checked_at"),
                "last_error":       s.get("watch_last_error"),
                "stream_health":    s.get("stream_health_status"),
                "needs_reconcile":  bool(s.get("needs_reconcile", 0)),
                "last_seen_slot":   s.get("last_seen_slot"),
                "last_seen_at":     s.get("last_seen_at"),
            } if s else None,
            "flow_24h": {
                "in_lamports":  f.get("total_in") or 0,
                "out_lamports": f.get("total_out") or 0,
                "events":       f.get("total_events") or 0,
            },
            "movements": [
                {
                    "slot":         m["slot"],
                    "block_time":   m["block_time"],
                    "net_lamports": m["net_lamports"],
                    "abs_lamports": m["abs_lamports"],
                    "direction":    m["direction"],
                    "counterparty": m["counterparty"],
                    "source":       m["source"],
                    "signature":    m["signature"],
                }
                for m in movements
            ],
        })
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route('/api/creator-pipeline-stats')
def api_creator_pipeline_stats():
    """
    Fleet-level pipeline health: history_status breakdown, watch coverage,
    24h movement volume.
    """
    try:
        import sqlite3 as _sq
        cdb = _creator_db_path()
        conn = _sq.connect(cdb, timeout=10)
        conn.row_factory = _sq.Row

        # history_status breakdown
        status_rows = conn.execute(
            """
            SELECT history_status, COUNT(*) as cnt
            FROM creator_profile
            GROUP BY history_status
            """
        ).fetchall()
        history_counts = {r["history_status"]: r["cnt"] for r in status_rows}
        total_profiled = sum(history_counts.values())

        # watch_status breakdown
        watch_rows = conn.execute(
            """
            SELECT COALESCE(watch_status, 'none') as ws, COUNT(*) as cnt
            FROM creator_activity_state
            GROUP BY ws
            """
        ).fetchall()
        watch_counts = {r["ws"]: r["cnt"] for r in watch_rows}

        # 24h movement totals
        cutoff = int(__import__('time').time()) - 86400
        flow = conn.execute(
            """
            SELECT
                COUNT(DISTINCT creator_address) as active_creators,
                SUM(CASE WHEN direction='in'  THEN abs_lamports ELSE 0 END) as total_in,
                SUM(CASE WHEN direction='out' THEN abs_lamports ELSE 0 END) as total_out,
                COUNT(*) as total_events
            FROM creator_sol_movements
            WHERE block_time >= ?
            """,
            (cutoff,)
        ).fetchone()

        conn.close()

        f = dict(flow) if flow else {}
        active_watches = watch_counts.get("active", 0)

        return jsonify({
            "total_profiled":    total_profiled,
            "history_breakdown": history_counts,
            "watch_breakdown":   watch_counts,
            "active_watches":    active_watches,
            "watch_pct":         round(active_watches / total_profiled * 100, 1) if total_profiled else 0,
            "baselined_pct":     round((history_counts.get("baselined", 0) / total_profiled * 100), 1) if total_profiled else 0,
            "flow_24h": {
                "active_creators": f.get("active_creators") or 0,
                "in_lamports":     f.get("total_in") or 0,
                "out_lamports":    f.get("total_out") or 0,
                "events":          f.get("total_events") or 0,
            },
        })
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route('/api/funder-webhook-events')
def funder_webhook_events():
    """Get recent funder webhook events (paginated)."""
    try:
        limit = request.args.get('limit', 50, type=int)
        offset = request.args.get('offset', 0, type=int)

        conn = db_connect(DB_PATH, timeout=15)
        cursor = conn.cursor()

        cursor.execute("""
            SELECT id, funder_address, signature, block_time, direction,
                   counterparty, amount_sol, mint, ingested_at
            FROM funder_webhook_events
            ORDER BY ingested_at DESC
            LIMIT ? OFFSET ?
        """, (limit, offset))

        rows = cursor.fetchall()
        result = []
        for row in rows:
            result.append({
                "id": row[0],
                "funder_address": row[1],
                "signature": row[2],
                "block_time": row[3],
                "direction": row[4],
                "counterparty": row[5],
                "amount_sol": row[6],
                "mint": row[7],
                "ingested_at": row[8],
            })

        conn.close()
        return jsonify(result)

    except Exception as e:
        return jsonify({"error": str(e)}), 500


