def _classify_risk(reputation_score: float) -> str:
    """Classify risk level from reputation score."""
    if reputation_score < 30:
        return 'HIGH_RISK'
    elif reputation_score < 60:
        return 'MEDIUM_RISK'
    else:
        return 'LOW_RISK'


