# START BACKGROUND WORKERS
# =========================================================================

def _sync_validated_tokens_to_tracker():
    """Register all validated token_pool_accounts into tracked_tokens on startup."""
    try:
        import sqlite3 as _sq
        from src.core.price_worker import PriceWorkerRegistry
        conn = _sq.connect(DB_PATH)
        mints = [r[0] for r in conn.execute(
            "SELECT DISTINCT mint FROM token_pool_accounts WHERE vault_validation_status IN ('validated','pending') AND is_active = 1"
        ).fetchall()]
        conn.close()
        if not mints:
            return
        # Find which mints already have a symbol cached
        conn2 = _sq.connect(DB_PATH)
        cached_symbols = {r[0] for r in conn2.execute(
            "SELECT mint FROM metadata_cache WHERE symbol IS NOT NULL AND symbol != '' AND symbol != 'UNKNOWN'"
        ).fetchall()}
        tracked_symbols = {r[0] for r in conn2.execute(
            "SELECT mint FROM tracked_tokens WHERE symbol IS NOT NULL AND symbol != ''"
        ).fetchall()}
        conn2.close()
        has_symbol = cached_symbols | tracked_symbols

        registry = PriceWorkerRegistry(DB_PATH)
        needs_symbol = []
        for mint in mints:
            registry.register_token(mint, priority_level='MEDIUM')
            if mint not in has_symbol:
                needs_symbol.append(mint)

        # Fetch symbols for tokens that don't have one yet (staggered to avoid burst)
        # Import is deferred into the thread to avoid importing pumpfun_curve_listener
        # at Flask startup — that module pulls in asyncio/aiohttp and can deadlock.
        import threading as _threading, time as _time
        def _staggered_symbol_fetch(mints_list):
            from src.core.pumpfun_curve_listener import _spawn_symbol_fetch
            for i, m in enumerate(mints_list):
                _time.sleep(i * 0.5)  # 500ms apart
                _spawn_symbol_fetch(m, DB_PATH)
        if needs_symbol:
            _threading.Thread(target=_staggered_symbol_fetch, args=(needs_symbol,), daemon=True).start()
            print(f"[PRICE_WORKER] Queued symbol fetch for {len(needs_symbol)} tokens without symbols")

        print(f"[PRICE_WORKER] Synced {len(mints)} validated tokens into tracked_tokens")
    except Exception as e:
        print(f"[WARNING] Token sync failed: {e}")


def start_background_workers():
    """Start price and liquidity workers in background threads"""
    print("[STARTUP_DIAG] start_background_workers: begin", flush=True)
    import os
    if os.environ.get('FLEX_ENABLE_FLASK_BACKGROUND_WORKERS', '0') != '1':
        print("[STARTUP_DIAG] optional Flask background workers skipped (set FLEX_ENABLE_FLASK_BACKGROUND_WORKERS=1 to enable)")
        return

    _sync_validated_tokens_to_tracker()
    print("[STARTUP_DIAG] _sync_validated_tokens_to_tracker: done", flush=True)

    if os.environ.get('FLEX_ENABLE_FLASK_PRICE_WORKER', '0') != '1':
        print("[PRICE_WORKER] Skipping worker start — listener process owns pricing (set FLEX_ENABLE_FLASK_PRICE_WORKER=1 to run it in Flask)")
    else:
        try:
            print("[STARTUP_DIAG] importing price_worker...", flush=True)
            from src.core.price_worker import start_price_worker
            print("[STARTUP_DIAG] starting price_worker...", flush=True)
            price_worker = start_price_worker(db_path=DB_PATH)
            print(f"[PRICE_WORKER] Background price worker started pid={os.getpid()}", flush=True)
        except Exception as e:
            print(f"[WARNING] Price worker failed to start: {e}")

    print("[STARTUP_DIAG] importing liquidity_worker...", flush=True)
    try:
        from src.core.liquidity_worker import start_liquidity_worker
        print("[STARTUP_DIAG] starting liquidity_worker...", flush=True)
        liquidity_worker = start_liquidity_worker(db_path=DB_PATH)
        print("[LIQUIDITY_WORKER] Background liquidity worker started - updating every 60s", flush=True)
    except Exception as e:
        print(f"[WARNING] Liquidity worker failed to start: {e}")

    try:
        import subprocess, sys as _sys
        def _run_monitor():
            import time as _time
            while True:
                _time.sleep(600)
                try:
                    subprocess.run(
                        [_sys.executable, '-m', 'src.core.token_behaviour_monitor', DB_PATH],
                        timeout=120,
                        capture_output=True,
                    )
                except Exception:
                    pass
        behaviour_thread = threading.Thread(target=_run_monitor, daemon=True)
        behaviour_thread.start()
        print("[TOKEN_BEHAVIOUR] Background classification monitor started - running every 10 min (subprocess)")
    except Exception as e:
        print(f"[WARNING] Token behaviour monitor failed to start: {e}")

    # RPC workers — run as daemons so they don't block the graph analyzer suite
    try:
        from src.core.second_hop_lite_worker import SecondHopLiteWorker as _SHL
        import time as _time
        def _shl_daemon():
            while True:
                try:
                    import time as _shl_t
                    _shl_started = int(_shl_t.time())
                    _SHL(DB_PATH).run()
                    # Incremental rescore — only creators touched by this batch
                    try:
                        import sqlite3 as _shl_sq
                        from src.core.risk_scoring_builder import RiskScoringBuilder as _RSB
                        _sc = _shl_sq.connect(DB_PATH, timeout=10)
                        _sc.execute("PRAGMA journal_mode=WAL")
                        _sf = [r[0] for r in _sc.execute(
                            "SELECT funder_address FROM second_hop_lite_queue WHERE status='done' AND scanned_at >= ?",
                            (_shl_started,)
                        ).fetchall()]
                        _ac = [r[0] for r in _sc.execute(
                            f"SELECT DISTINCT creator_address FROM creator_funders WHERE funder_address IN ({','.join('?'*len(_sf))})",
                            _sf
                        ).fetchall()] if _sf else []
                        _sc.close()
                        if _ac:
                            _RSB(DB_PATH).run_incremental(_ac)
                            print(f"[SHL_DAEMON] incremental rescore: {len(_sf)} funders → {len(_ac)} creators", flush=True)
                    except Exception as _re:
                        print(f"[SHL_DAEMON] incremental rescore error: {_re}", flush=True)
                except Exception as _e:
                    print(f"[SHL_DAEMON] error: {_e}")
                _time.sleep(300)  # 5 min between runs
        threading.Thread(target=_shl_daemon, daemon=True, name="shl-daemon").start()
        print("[SHL_DAEMON] SecondHopLiteWorker daemon started (5 min loop)")
    except Exception as e:
        print(f"[WARNING] SecondHopLiteWorker daemon failed to start: {e}")

    try:
        from src.core.creator_outbound_worker import CreatorOutboundWorker as _COW
        import time as _time
        def _cow_daemon():
            while True:
                try:
                    _COW(DB_PATH).run()
                except Exception as _e:
                    print(f"[COW_DAEMON] error: {_e}")
                _time.sleep(300)  # 5 min between runs
        threading.Thread(target=_cow_daemon, daemon=True, name="cow-daemon").start()
        print("[COW_DAEMON] CreatorOutboundWorker daemon started (5 min loop)")
    except Exception as e:
        print(f"[WARNING] CreatorOutboundWorker daemon failed to start: {e}")

