@app.route('/api/extract-token/<signature>')
def api_extract_token(signature: str):
    """Extract token mint and metadata from a transaction signature."""
    try:
        import aiohttp
        import asyncio

        async def fetch_tx():
            payload = {
                "jsonrpc": "2.0",
                "id": 1,
                "method": "getTransaction",
                "params": [signature, {"encoding": "jsonParsed", "maxSupportedTransactionVersion": 0}]
            }

            async with aiohttp.ClientSession() as session:
                async with session.post("https://api.mainnet-beta.solana.com", json=payload, timeout=aiohttp.ClientTimeout(total=30)) as resp:
                    return await resp.json()

        data = asyncio.run(fetch_tx())

        if data.get("error"):
            return jsonify({'error': f"RPC Error: {data['error'].get('message', 'Unknown')}"}), 400

        tx = data.get("result")
        if not tx:
            return jsonify({'error': 'Transaction not found'}), 404

        # Look for token transfers in instructions
        instructions = tx.get("transaction", {}).get("message", {}).get("instructions", [])
        tokens_found = []

        for inst in instructions:
            parsed = inst.get("parsed", {})

            # Check for token transfers
            if parsed.get("type") == "transfer" and "mint" in parsed.get("info", {}):
                mint = parsed["info"]["mint"]
                amount = parsed["info"].get("tokenAmount", {}).get("uiAmount", 0)
                tokens_found.append({"mint": mint, "amount": amount})

            # Check for swap/AMM interactions
            if parsed.get("type") == "swap":
                info = parsed.get("info", {})
                tokens_found.append({
                    "type": "swap",
                    "inputMint": info.get("inputMint"),
                    "outputMint": info.get("outputMint"),
                    "inputAmount": info.get("inputAmount"),
                    "outputAmount": info.get("outputAmount")
                })

        # Get token metadata from database
        conn = db_connect(DB_PATH, timeout=5)
        for token in tokens_found:
            mint = token.get("mint") or token.get("outputMint")
            if mint:
                row = conn.execute(
                    "SELECT symbol, name FROM tracked_tokens WHERE mint=? LIMIT 1",
                    (mint,)
                ).fetchone()
                if row:
                    token["symbol"] = row[0]
                    token["name"] = row[1]
        conn.close()

        return jsonify({
            'signature': signature,
            'tokens': tokens_found,
            'instruction_count': len(instructions)
        })

    except Exception as e:
        print(f"[TOKEN_EXTRACT] Error: {e}")
        return jsonify({'error': str(e)}), 500

@app.route('/api/subprov-enriched/<signature>')
def api_subprov_enriched(signature: str):
    """Get SUB_PROV transaction with extracted token name for display. Stores in DB."""
    try:
        import aiohttp
        import asyncio

        async def fetch_tx():
            payload = {
                "jsonrpc": "2.0",
                "id": 1,
                "method": "getTransaction",
                "params": [signature, {"encoding": "jsonParsed", "maxSupportedTransactionVersion": 0}]
            }

            async with aiohttp.ClientSession() as session:
                async with session.post("https://api.mainnet-beta.solana.com", json=payload, timeout=aiohttp.ClientTimeout(total=30)) as resp:
                    return await resp.json()

        data = asyncio.run(fetch_tx())

        if data.get("error"):
            return jsonify({'error': f"RPC Error: {data['error'].get('message', 'Unknown')}"}), 400

        tx = data.get("result")
        if not tx:
            return jsonify({'error': 'Transaction not found'}), 404

        block_time = tx.get("blockTime")
        account_keys = tx.get("transaction", {}).get("message", {}).get("accountKeys", [])
        instructions = tx.get("transaction", {}).get("message", {}).get("instructions", [])

        # Extract SUB_PROV wallet (likely the fee payer or first signer)
        subprov_wallet = account_keys[0] if account_keys else None

        # Find output token from swap in this transaction
        output_mint = None
        output_amount = None

        for inst in instructions:
            parsed = inst.get("parsed", {})
            if parsed.get("type") == "swap":
                info = parsed.get("info", {})
                output_mint = info.get("outputMint")
                output_amount = info.get("outputAmount")
                break

        # If no swap found, check destination accounts for token activity
        if not output_mint:
            import requests as _req
            rpc_url = os.environ.get("HELIUS_RPC_URL") or "https://api.mainnet-beta.solana.com"

            # Extract destination accounts from account balance changes
            # Parse meta.preBalances and postBalances to find accounts that received SOL
            destinations = []
            meta = tx.get("meta", {})
            pre_balances = meta.get("preBalances", [])
            post_balances = meta.get("postBalances", [])

            # Find accounts where balance increased (received SOL)
            if len(account_keys) == len(pre_balances) == len(post_balances):
                for i, addr in enumerate(account_keys):
                    addr_str = addr if isinstance(addr, str) else addr.get("pubkey", "")
                    if addr_str and addr_str != subprov_wallet:
                        balance_change = post_balances[i] - pre_balances[i]
                        if balance_change > 0:  # Received SOL
                            destinations.append(addr_str)

            print(f"[SUB_PROV_ENRICHMENT] Found {len(destinations)} destinations: {destinations[:2]}", flush=True)

            # Check each destination's recent transactions for token buys
            print(f"[SUBPROV_ENRICHED] Found {len(destinations)} destinations, checking for token buys...", flush=True)
            for dest_account in destinations[:3]:  # Check up to 3 destinations
                try:
                    payload2 = {
                        "jsonrpc": "2.0",
                        "id": 1,
                        "method": "getSignaturesForAddress",
                        "params": [dest_account, {"limit": 5}]
                    }
                    resp2 = _req.post(rpc_url, json=payload2, timeout=10)
                    sigs = resp2.json().get("result", [])

                    # Check destination's transactions for token transfers (they receive tokens)
                    for sig_obj in sigs:
                        dest_tx_sig = sig_obj.get("signature")
                        if not dest_tx_sig or sig_obj.get("err") is not None:
                            continue

                        payload3 = {
                            "jsonrpc": "2.0",
                            "id": 1,
                            "method": "getTransaction",
                            "params": [dest_tx_sig, {"encoding": "jsonParsed", "maxSupportedTransactionVersion": 0}]
                        }
                        resp3 = _req.post(rpc_url, json=payload3, timeout=10)
                        dest_tx = resp3.json().get("result")
                        if not dest_tx:
                            continue

                        # Look for tokenTransfers where dest_account received tokens
                        token_transfers = dest_tx.get("tokenTransfers", [])
                        for tt in token_transfers:
                            recipient = tt.get("toUserAccount") or tt.get("destination")
                            if recipient == dest_account:
                                output_mint = tt.get("mint")
                                output_amount = tt.get("tokenAmount", {}).get("uiAmount", 0)
                                break

                        if output_mint:
                            break

                    if output_mint:
                        break
                except Exception as _e:
                    pass

        # Get token name from database
        token_symbol = "UNKNOWN"
        if output_mint:
            conn = db_connect(DB_PATH, timeout=5)
            row = conn.execute(
                "SELECT symbol FROM tracked_tokens WHERE mint=? LIMIT 1",
                (output_mint,)
            ).fetchone()
            if row:
                token_symbol = row[0]

            # Store/update in wt_sub_provisioners if we have the wallet
            if subprov_wallet:
                conn.execute("""
                    INSERT OR IGNORE INTO wt_sub_provisioners (address, first_seen_at, scan_status)
                    VALUES (?, ?, 'confirmed')
                """, (subprov_wallet, block_time))

                conn.execute("""
                    UPDATE wt_sub_provisioners SET
                        token_mint = ?,
                        token_symbol = ?,
                        traded_amount = ?,
                        last_trade_tx = ?,
                        last_trade_at = ?,
                        scan_status = 'confirmed'
                    WHERE address = ?
                """, (output_mint, token_symbol, output_amount, signature, block_time, subprov_wallet))
                conn.commit()

            conn.close()

        display_text = f'SUB_PROV_inbound · {output_amount or "?"} {token_symbol}' if output_mint else 'SUB_PROV_inbound · Unknown token'

        return jsonify({
            'signature': signature,
            'subprov_wallet': subprov_wallet,
            'token_mint': output_mint,
            'token_symbol': token_symbol,
            'output_amount': output_amount,
            'block_time': block_time,
            'display_text': display_text,
            'stored': True
        })

    except Exception as e:
        print(f"[SUBPROV_ENRICHED] Error: {e}")
        return jsonify({'error': str(e)}), 500

# =========================================================================
# MAIN
# =========================================================================

if __name__ == '__main__':
    import logging
    log = logging.getLogger('werkzeug')
    log.setLevel(logging.ERROR)

    # Kill any orphaned pumpfun_curve_listener processes that hold DB connections.
    # These get detached via start_new_session=True in cleanup_and_restart() and
    # survive Flask restarts, holding file descriptors that block DB writes.
    try:
        import subprocess as _sp
        _result = _sp.run(['pgrep', '-f', 'pumpfun_curve_listener'], capture_output=True, text=True)
        _orphan_pids = [int(p) for p in _result.stdout.split() if p.strip()]
        if _orphan_pids:
            print(f"[STARTUP] Killing {len(_orphan_pids)} orphaned curve_listener process(es): {_orphan_pids}", flush=True)
            for _pid in _orphan_pids:
                try:
                    import os as _os
                    _os.kill(_pid, 15)  # SIGTERM
                except ProcessLookupError:
                    pass
            import time as _t; _t.sleep(1)  # give them a moment to exit
    except Exception as _e:
        print(f"[STARTUP] orphan cleanup skipped: {_e}", flush=True)

    # Ensure watchtower tables in a background thread — never block app.run()
    # The _wt_tables_ready guard in webhook_watchtower() handles first-hit init.
    def _init_wt_tables():
        global _wt_tables_ready
        import time as _t
        for attempt in range(10):
            try:
                _c = db_connect(DB_PATH, timeout=5)
                _ensure_watchtower_tables(_c)
                _c.commit()
                _c.close()
                _wt_tables_ready = True
                print("[STARTUP] Watchtower tables verified", flush=True)
                break
            except Exception as _e:
                print(f"[STARTUP] watchtower table init attempt {attempt+1} failed: {_e}", flush=True)
                _t.sleep(3)
        else:
            print("[STARTUP] WARNING: watchtower tables could not be verified after 10 attempts", flush=True)
            return
        # Run WATCH pipeline after tables are ready
        try:
            _pc = db_connect(DB_PATH, timeout=30)
            result = _run_watch_pipeline(_pc)
            _pc.close()
            print(f"[STARTUP] WATCH pipeline complete: {result}", flush=True)
        except Exception as _pe:
            print(f"[STARTUP] WATCH pipeline error: {_pe}", flush=True)
    threading.Thread(target=_init_wt_tables, daemon=True, name="wt-table-init").start()

    # Start single DB writer thread — must be first, before any other workers
    try:
        from src.core.db_writer import start_db_writer
        start_db_writer(DB_PATH)
        print("[STARTUP] DB single-writer thread started", flush=True)
    except Exception as _e:
        print(f"[STARTUP] WARNING: DB writer failed to start: {_e}", flush=True)

    # WAL checkpoint maintenance thread
    def _wal_checkpoint_loop():
        import time as _t
        import os as _os2
        while True:
            _t.sleep(30)
            try:
                wal_path = DB_PATH + "-wal"
                wal_mb = _os2.path.getsize(wal_path) / 1024 / 1024 if _os2.path.exists(wal_path) else 0
                if wal_mb > 500:
                    # Emergency — try TRUNCATE with long timeout to wait out readers
                    mode = "TRUNCATE"
                    timeout = 60
                elif wal_mb > 100:
                    mode = "RESTART"
                    timeout = 30
                else:
                    mode = "PASSIVE"
                    timeout = 15
                _wc = db_connect(DB_PATH, timeout=timeout)
                _wc.execute(f"PRAGMA busy_timeout={timeout * 1000}")
                result = _wc.execute(f"PRAGMA wal_checkpoint({mode})").fetchone()
                _wc.close()
                # Log if checkpoint couldn't write all frames (busy readers)
                if result and result[1] != result[2]:
                    print(f"[WAL] {mode} partial: {result[2]}/{result[1]} frames written, WAL={wal_mb:.0f}MB", flush=True)
                _wt_heartbeat("flask-app", "ok", {"pid": _os.getpid(), "wal_mb": round(wal_mb, 1)})
            except Exception:
                pass
    threading.Thread(target=_wal_checkpoint_loop, daemon=True, name="wal-checkpoint").start()

    # Register internal API blueprint
    try:
        from src.core.internal_api import internal_bp
        app.register_blueprint(internal_bp)
        print("[STARTUP] Internal API blueprint registered (/api/internal/*)", flush=True)
    except Exception as _e:
        print(f"[STARTUP] WARNING: Internal API blueprint failed: {_e}", flush=True)

    import os as _os
    try:
        from src.core.ws_snapshot_logger import _LOG_PATH as _ws_log_path
        _ws_log_abs = _os.path.abspath(_ws_log_path)
    except Exception:
        _ws_log_abs = '(unavailable)'
    print("[STARTUP] ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
    print(f"[STARTUP] role=flask pid={_os.getpid()}")
    print(f"[STARTUP] db={_os.path.abspath(DB_PATH)}")
    print(f"[STARTUP] ws_snapshot_log={_ws_log_abs}")
    print(f"[STARTUP] cwd={_os.getcwd()}")
    print(f"[STARTUP] FLEX_WS_DISABLED={_os.environ.get('FLEX_WS_DISABLED','0')}")
    print("[STARTUP] ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
    print("[FLASK] Starting Migration Tracker UI...")
    print("[FLASK] Dashboard available at http://localhost:5002")
    print(f"[FLASK] Database: {_os.path.abspath(DB_PATH)}")

    # Prediction builder daemon — score new migrations and drain rescore queue
    def _prediction_daemon():
        import time as _t
        _t.sleep(2)  # let DB settle after startup
        while True:
            try:
                from src.core.token_prediction_builder import TokenPredictionBuilder
                TokenPredictionBuilder(DB_PATH).run()
            except Exception as _e:
                if "database is locked" in str(_e):
                    print(f"[PREDICTION_DAEMON] DB locked, retrying in 15s", flush=True)
                    _t.sleep(15)
                    continue
                print(f"[PREDICTION_DAEMON] error: {_e}", flush=True)
            _t.sleep(120)  # run every 2 minutes

    threading.Thread(target=_prediction_daemon, daemon=True, name="prediction-daemon").start()
    print("[PREDICTION_DAEMON] Token prediction daemon started (2 min loop)", flush=True)


    # Creator resolution queue daemon — process pending resolution jobs every 30s
    def _creator_resolution_daemon():
        import time as _t
        _t.sleep(3)
        while True:
            try:
                from src.core.creator_resolution_queue import process_queue
                result = process_queue(DB_PATH, limit=10)
                if result.get("processed", 0) > 0:
                    print(f"[CREATOR_RES] processed={result['processed']} resolved={result.get('resolved',0)} funding_enqueued={result.get('funding_enqueued',0)}", flush=True)
            except Exception as _e:
                print(f"[CREATOR_RES] error: {_e}", flush=True)
            _t.sleep(30)

    threading.Thread(target=_creator_resolution_daemon, daemon=True, name="creator-resolution-daemon").start()
    print("[CREATOR_RES] Creator resolution daemon started (30s loop)", flush=True)

    # Under gunicorn, _wt_startup_once() (before_request) starts these — skip here
    if not _wt_startup_done:
        _start_wt_infra_processor()
        _start_wt_candidate_processor()
        _start_wt_operator_ttl_reaper()
        _start_hub_backfill_worker()
    print("[WT] Webhook queue processors started", flush=True)

    # Seed wt_wallet_tier from _WT_INFRA_ROLES
    def _seed_wallet_tiers():
        try:
            _tc = db_connect(DB_PATH, timeout=10)
            for addr, role in _WT_INFRA_ROLES.items():
                tier = 1 if role in ("SIGNALLER", "SUB_PROV") else 2
                _tc.execute("""
                    INSERT OR IGNORE INTO wt_wallet_tier
                        (wallet_address, tier, role, auto_classified)
                    VALUES (?, ?, ?, 1)
                """, (addr, tier, role))
            _tc.commit()
            _tc.close()
            print(f"[WT] wt_wallet_tier seeded ({len(_WT_INFRA_ROLES)} infra addresses)", flush=True)
        except Exception as _e:
            print(f"[WT] tier seed error: {_e}", flush=True)
    _seed_wallet_tiers()

    # Rebuild in-memory corridor state from DB (handles server restarts)
    def _seed_corridors():
        try:
            _cc = db_connect(DB_PATH, timeout=10)
            rows = _cc.execute("""
                SELECT wallet_address, treasury_sig, treasury_ts, treasury_sol,
                       signaller_sig, signaller_ts, signaller_lag_s, f5m_expires_at
                FROM wt_launch_corridors
                WHERE state = 'CORRIDOR_ACTIVE'
            """).fetchall()
            _cc.close()
            with _wt_corridors_lock:
                for r in rows:
                    _wt_corridors[r[0]] = {
                        "treasury_sig": r[1], "treasury_ts":  r[2],
                        "treasury_sol": r[3], "signaller_sig": r[4],
                        "signaller_ts": r[5], "lag_s":         r[6],
                        "state":        "CORRIDOR_ACTIVE",
                        "f5m_expires":  r[7],
                    }
                    _wt_candidate_set.add(r[0])
            if rows:
                print(f"[WT_CORRIDOR] Resumed {len(rows)} active corridor(s) from DB", flush=True)
        except Exception as _e:
            print(f"[WT_CORRIDOR] seed error: {_e}", flush=True)
    _seed_corridors()

    if not _wt_startup_done:
        _start_relay_counterparty_discovery_worker(DB_PATH)
        _start_corridor_monitor_worker(DB_PATH)
        _start_swarm_migration_scanner(DB_PATH)

    _start_watchtower_activation_poller(DB_PATH, interval_seconds=60)
    _start_staged_wallet_poller(DB_PATH, interval_seconds=600)
    _backfill_wt_creator_launches(DB_PATH)

    # ── Webhook lifecycle manager ─────────────────────────────────────────────
    def _start_webhook_reconciliation_worker():
        import asyncio as _asyncio
        from src.analysis.webhook_manager import run_reconciliation_worker, ensure_schema
        import sqlite3 as _sq
        try:
            _conn = _sq.connect(DB_PATH)
            ensure_schema(_conn)
            _conn.close()
        except Exception as _e:
            print(f"[WH_MGR] schema init error: {_e}", flush=True)

        loop = _asyncio.new_event_loop()
        _asyncio.set_event_loop(loop)
        try:
            loop.run_until_complete(run_reconciliation_worker(DB_PATH, interval_s=120))
        except Exception as _e:
            print(f"[WH_MGR] reconciliation worker crashed: {_e}", flush=True)
        finally:
            loop.close()

    threading.Thread(
        target=_start_webhook_reconciliation_worker,
        daemon=True,
        name="wh-reconciliation-worker",
    ).start()
    print("[WH_MGR] Webhook reconciliation worker started (120s interval)", flush=True)

    # WATCHTOWER CREATE Interceptor — optional real-time buy execution
    if os.environ.get("ENABLE_CREATE_INTERCEPTOR", "").lower() == "true":
        try:
            from src.core.watchtower.create_interceptor import start as start_interceptor
            from src.core.watchtower.passive_validator import startup as init_validator
            start_interceptor(db_path=DB_PATH)
            init_validator()
            print("[STARTUP] WATCHTOWER CREATE Interceptor ENABLED (mode=%s)" % os.environ.get("INTERCEPTOR_MODE", "ARMED"), flush=True)
        except Exception as _e:
            print(f"[STARTUP] CREATE Interceptor startup error (will continue without it): {_e}", flush=True)

    # Pre-warm homepage + pumpfun caches so first page loads are fast
    def _prewarm_cache():
        import time as _t
        _t.sleep(3)  # let startup DB writes settle first
        _refresh_migrated_tokens_cache()
        _refresh_pumpfun_live_cache()
        print(f"[CACHE] migrated-tokens + pumpfun/live pre-warm triggered", flush=True)
    threading.Thread(target=_prewarm_cache, daemon=True).start()

    # Start background workers in a thread so app.run() binds immediately
    def _deferred_workers():
        import time as _t
        _t.sleep(0.5)  # let Werkzeug finish binding
        start_background_workers()
        print("[STARTUP_DIAG] start_background_workers: complete", flush=True)

    threading.Thread(target=_deferred_workers, daemon=True).start()
    print("[STARTUP_DIAG] calling app.run() — workers starting in background", flush=True)

    app.run(host='0.0.0.0', port=5002, debug=False, threaded=True)
